      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_archive_category_id_idx ON winscope_archive(category, id DESC)");
      // Ham fikstur arşivi: API-Football'dan gelen her fixture kalıcı tutulur.
      // Fixture ID tekildir; sonraki API cevapları aynı satırı günceller, eski kayıt silinmez.
