// API-Football: tüm istekler tek, öncelikli ve hız kontrollü kuyruktan geçer.
// ULTRA sınırı 450/dk olsa da uygulama güvenlik payıyla yaklaşık 50/dk hedefler.
// Canlı fikstür/oran/istatistik istekleri, maç önü sayfalı oran taramasının önüne alınır.
let providerQueue = [];
let providerQueueRunning = false;
let lastProviderRequestAt = 0;
let providerCooldownUntil = 0;
const PROVIDER_MIN_INTERVAL_MS = Math.max(1000, Number(process.env.API_FOOTBALL_MIN_INTERVAL_MS) || 1200);
let providerQueueSequence = 0;
let lastProviderUsageLogAt = 0;
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

function providerRequestPriority(pathname) {
  const path = String(pathname || "");
  if (/\/fixtures\?live=all|\/odds\/live|\/fixtures\/statistics\?fixture=/.test(path)) return 0;
  if (/\/fixtures\?id=/.test(path)) return 0;
  if (/\/odds\?date=.*page=/.test(path)) return 2;
  return 1;
}

function logProviderUsage(response) {
  const now = Date.now();
  if (now - lastProviderUsageLogAt < 60_000) return;
  const minuteLimit = response.headers.get("x-ratelimit-limit");
  const minuteRemaining = response.headers.get("x-ratelimit-remaining");
  const dailyLimit = response.headers.get("x-ratelimit-requests-limit");
  const dailyRemaining = response.headers.get("x-ratelimit-requests-remaining");
  if (minuteLimit || minuteRemaining || dailyLimit || dailyRemaining) {
    console.log(`[API USAGE] minuteRemaining=${minuteRemaining ?? "?"}/${minuteLimit ?? "?"} dailyRemaining=${dailyRemaining ?? "?"}/${dailyLimit ?? "?"} queue=${providerQueue.length}`);
    lastProviderUsageLogAt = now;
  }
}

function enqueueProviderRequest(run, priority = 1) {
  return new Promise((resolve, reject) => {
    providerQueue.push({ run, priority, sequence: providerQueueSequence++, resolve, reject });
    providerQueue.sort((a, b) => a.priority - b.priority || a.sequence - b.sequence);
    void pumpProviderQueue();
  });
}

async function pumpProviderQueue() {
  if (providerQueueRunning) return;
  providerQueueRunning = true;
  try {
    while (providerQueue.length) {
      const item = providerQueue.shift();
      try {
        const now = Date.now();
        const allowedAt = Math.max(lastProviderRequestAt + PROVIDER_MIN_INTERVAL_MS, providerCooldownUntil);
        if (allowedAt > Date.now()) await delay(allowedAt - Date.now());
        lastProviderRequestAt = Date.now();
        item.resolve(await item.run());
      } catch (error) {
        item.reject(error);
      }
    }
  } finally {
    providerQueueRunning = false;
    if (providerQueue.length) void pumpProviderQueue();
  }
}

async function cachedProviderRequest(cacheKey, pathname, ttlMs = 30000) {
  const now = Date.now();
  const cached = providerCache.get(cacheKey);
  if (cached && now - cached.at < ttlMs) return cached.payload;
  if (providerInFlight.has(cacheKey)) return providerInFlight.get(cacheKey);
  if (!API_KEY) throw new Error("Render Environment Variables içinde API_FOOTBALL_KEY eksik.");

  const priority = providerRequestPriority(pathname);
  const task = enqueueProviderRequest(async () => {
    const secondCheck = providerCache.get(cacheKey);
    if (secondCheck && Date.now() - secondCheck.at < ttlMs) return secondCheck.payload;
    const response = await fetch(`${BASE_URL}${pathname}`, {
      headers: { "x-apisports-key": API_KEY, Accept: "application/json" },
      signal: AbortSignal.timeout(15000)
    });
    logProviderUsage(response);
    const raw = await response.text();
    let payload;
    try { payload = raw ? JSON.parse(raw) : {}; } catch { throw new Error("API-Football geçerli JSON döndürmedi."); }
    // Her gerçek /fixtures API cevabındaki fikstürleri analizden bağımsız arşivle.
    // Arşiv yazımı başarısız olsa bile maç akışını kesmez.
    if (String(pathname || "").split("?")[0] === "/fixtures") {
      await archiveProviderFixtures(pathname, payload);
    }
    if (String(pathname || "").split("?")[0] === "/odds") {
      await archiveProviderOdds(pathname, payload);
    }
    const errors = payload.errors && Object.keys(payload.errors).length ? payload.errors : null;
    const errorText = errors ? JSON.stringify(errors) : "";
    if (!response.ok || errors) {
      if (response.status === 429 || /rate.?limit|too many requests|per-minute|per-second/i.test(errorText)) {
        const retryHeader = Number(response.headers.get("retry-after")) || 0;
        const retryBody = Number((errorText.match(/retry after\s+(\d+)/i) || [])[1]) || 0;
        const waitMs = Math.max(90_000, (Math.max(retryHeader, retryBody) + 5) * 1000);
        providerCooldownUntil = Math.max(providerCooldownUntil, Date.now() + waitMs);
        console.error(`[API 429] ${Math.ceil(waitMs / 1000)} sn bekleme; istek önceliği=${priority}, kuyruk=${providerQueue.length}. Aynı API anahtarını kullanan başka süreç olup olmadığını kontrol edin.`);
        throw new Error(`API-Football hız sınırı; ${Math.ceil(waitMs / 1000)} saniye bekleme uygulandı. ${errorText}`);
      }
      throw new Error(`API-Football hatası: ${errors ? errorText : `HTTP ${response.status}`}`);
    }
    providerCache.set(cacheKey, { at: Date.now(), payload });
    if (providerCache.size > 2500) {
      const cutoff = Date.now() - 6 * 60 * 60 * 1000;
      for (const [key, value] of providerCache) if (value.at < cutoff) providerCache.delete(key);
      while (providerCache.size > 2000) providerCache.delete(providerCache.keys().next().value);
    }
    return payload;
  }, priority);
  providerInFlight.set(cacheKey, task);
  try { return await task; }
  finally { providerInFlight.delete(cacheKey); }
}

function normalizeProviderMatch(match) {
  const homeName = match.teams?.home?.name || match.home || "Ev sahibi";
  const awayName = match.teams?.away?.name || match.away || "Deplasman";
  const leagueName = match.league?.name || match.league || "Lig";
  const countryName = match.league?.country || match.country || "";
  const idNum = Number(match.fixture?.id ?? match.id) || 0;
  const periodStatus = String(match.fixture?.status?.short || match.status || "NS").toUpperCase();
  let status = periodStatus;
  if (["FT", "AET", "PEN"].includes(status)) status = "FT";
  else if (["1H", "2H", "HT", "LIVE", "IN_PLAY", "ET", "BT", "P"].includes(status)) status = "LIVE";
  else if (["NS", "TBD", "PST", "CANC", "ABD", "AWD", "WO"].includes(status)) status = status === "NS" ? "NS" : status;
  return {
    id: idNum, homeId: Number(match.teams?.home?.id) || null, awayId: Number(match.teams?.away?.id) || null,
    leagueId: Number(match.league?.id) || null, season: Number(match.league?.season) || null,
    league: String(leagueName), country: String(countryName),
    minute: match.fixture?.status?.elapsed ?? match.minute ?? null, status, periodStatus,
    home: String(homeName), away: String(awayName),
    homeScore: match.goals?.home ?? 0, awayScore: match.goals?.away ?? 0,
    htHomeScore: match.score?.halftime?.home ?? null, htAwayScore: match.score?.halftime?.away ?? null,
    fixtureDate: match.fixture?.date || match.kickoff_utc || null
  };
}

function computeAnalysis(match) {
  const minute = Number(match.minute || 0);
  const home = Number(match.homeScore || 0), away = Number(match.awayScore || 0);
  const total = home + away, live = match.status === "LIVE", finished = match.status === "FT";
  let ht = "Tahmin: 1-0", ft = "Tahmin: 2-1", mainPick = "MS 2.5 ÜST", alternative = "KG VAR";
  if (finished) {
    ht = `${match.htHomeScore ?? "?"}-${match.htAwayScore ?? "?"}`;
    ft = `${home}-${away}`;
  } else if (live) {
    if (minute >= 45 && match.htHomeScore != null && match.htAwayScore != null) ht = `${match.htHomeScore}-${match.htAwayScore} (İY Gerçek)`;
    else if (minute < 45 && total > 0) ht = `Tahmin: ${home}-${away}`;
    else if (minute <= 30) ht = "Tahmin: 1-0";
    else ht = "Tahmin: 0-0";
    ft = minute >= 75 ? `Tahmin: ${home}-${away}` : `Tahmin: ${home + 1}-${away}`;
    if (minute < 33 && total === 0) { mainPick = "İY 0.5 ÜST"; alternative = "MS 1.5 ÜST"; }
    else if (minute >= 33 && minute < 45 && total === 0) { mainPick = "MS 1.5 ÜST"; alternative = "KG VAR"; }
    else if (minute >= 45 && total < 2) { mainPick = "MS 1.5 ÜST"; alternative = "KG VAR"; }
    else { mainPick = "MS 1.5 ÜST"; alternative = "KG VAR"; }
  } else {
    ht = "Tahmin: 1-0";
    ft = "Tahmin: 2-1";
    mainPick = "MS 2.5 ÜST"; alternative = "KG VAR";
  }
  return { halfTimeScore: ht, fullTimeScore: ft, mainPick, alternative, surprise: "MS 3.5 ÜST" };
}

function bookmakerRows(oddsRow) {
  if (!oddsRow) return [];
  if (Array.isArray(oddsRow.bookmakers) && oddsRow.bookmakers.length) return oddsRow.bookmakers;
  if (Array.isArray(oddsRow.odds) && oddsRow.odds.length) {
    return [{
      name: oddsRow.bookmaker?.name || oddsRow.bookmaker || oddsRow.source || "API-Football",
      bets: oddsRow.odds.map(item => ({ name: item.name || item.bet || "", values: item.values || [] }))
    }];
  }
  return [];
}

function oddsForFixture(oddsRow, { includeFirstHalfBtts = false } = {}) {
  const markets = new Map();
  const add = (book, key, side, odd) => {
    if (!Number.isFinite(odd) || odd <= 1.01) return;
    const mapKey = `${book}|${key}`;
    if (!markets.has(mapKey)) markets.set(mapKey, { market: key, bookmaker: book, over: null, under: null, yes: null, no: null, home: null, draw: null, away: null });
    const item = markets.get(mapKey);
    item[side] = odd;
  };
  for (const bookmaker of bookmakerRows(oddsRow)) {
    const book = String(bookmaker.name || "Kaynak belirtilmedi");
    for (const bet of (bookmaker.bets || [])) {
      const name = String(bet.name || "").toLowerCase().replace(/[–—]/g, "-");
      const isHalf = /first half|1st half|half.?time|1st period|first period/.test(name);
      const isHomeTeam = /home team|home goals|team 1 total|team 1 goals|team total - home/.test(name);
      const isAwayTeam = /away team|away goals|team 2 total|team 2 goals|team total - away/.test(name);
      const isBtts = /both teams to score|both teams score|btts/.test(name);
      const isTotal = /over.?under|total goals|match goals|goal line|goals total|total/.test(name) && !isHomeTeam && !isAwayTeam;
      const isWinner = /match winner|1x2|full.?time result|match result|regular time result|winner/.test(name);
      for (const value of (bet.values || [])) {
        const label = String(value.value ?? value.name ?? "").toLowerCase().trim();
        const odd = Number(value.odd);
        if (!Number.isFinite(odd) || odd <= 1.01) continue;
        if (isWinner) {
          if (/^(home|1|team 1|1 \(home\))$/.test(label)) add(book, "MS 1", "home", odd);
          else if (/^(draw|x|tie)$/.test(label)) add(book, "MS 1", "draw", odd);
          else if (/^(away|2|team 2|2 \(away\))$/.test(label)) add(book, "MS 1", "away", odd);
          continue;
        }
        if (isBtts) {
          const bttsMarket = isHalf && includeFirstHalfBtts ? "İY KG VAR" : "KG VAR";
          if (/^(yes|y|both teams to score - yes)$/.test(label)) add(book, bttsMarket, "yes", odd);
          else if (/^(no|n|both teams to score - no)$/.test(label)) add(book, bttsMarket, "no", odd);
          continue;
        }
        const overMatch = label.match(/over\s*([0-9]+[.,][0-9]+)/);
        const underMatch = label.match(/under\s*([0-9]+[.,][0-9]+)/);
        const lineMatch = label.match(/([0-9]+[.,][0-9]+)/);
        const line = (overMatch || underMatch || lineMatch)?.[1]?.replace(',', '.');
        if (!line) continue;
        const side = overMatch ? "over" : underMatch ? "under" : null;
        if (!side) continue;
        let key = null;
        if (isHomeTeam && [0.5, 1.5].includes(Number(line))) key = `EV ${line} ÜST`;
        else if (isAwayTeam && [0.5, 1.5].includes(Number(line))) key = `DEP ${line} ÜST`;
        else if (isHalf && [0.5, 1.5, 2.5].includes(Number(line))) key = `İY ${line} ÜST`;
        else if (isTotal && [0.5, 1.5, 2.5, 3.5, 5.5].includes(Number(line))) key = `MS ${line} ÜST`;
        if (key) add(book, key, side, odd);
      }
    }
  }
  const candidates = [];
  for (const item of markets.values()) {
    let pct = null;
    let outcomeProbabilities = null;
    if (item.over && item.under) pct = 100 * (1 / item.over) / ((1 / item.over) + (1 / item.under));
    else if (item.yes && item.no) pct = 100 * (1 / item.yes) / ((1 / item.yes) + (1 / item.no));
    else if (item.home && item.draw && item.away) {
      const inv = [1 / item.home, 1 / item.draw, 1 / item.away], sum = inv.reduce((a,b)=>a+b,0);
      outcomeProbabilities = { home: 100 * inv[0] / sum, draw: 100 * inv[1] / sum, away: 100 * inv[2] / sum };
      pct = outcomeProbabilities.home;
    }
    const odd = item.over || item.yes || item.home;
    // Bazı canlı feed'lerde yalnızca Over/Yes fiyatı gelir; eksik karşı taraf
    // nedeniyle pazarı atlama. Tek taraflı implied probability muhafazakâr kullanılır.
    if (pct == null && Number.isFinite(Number(odd)) && Number(odd) > 1.01) pct = 100 / Number(odd);
    if (pct == null || !Number.isFinite(pct)) continue;
    const ranks = { "EV 1.5 ÜST": 1, "DEP 1.5 ÜST": 1, "İY 0.5 ÜST": 2, "MS 0.5 ÜST": 2, "İY 1.5 ÜST": 3, "MS 1.5 ÜST": 3, "MS 2.5 ÜST": 4, "KG VAR": 5, "MS 3.5 ÜST": 6, "MS 4.5 ÜST": 7, "MS 5.5 ÜST": 8 };
    candidates.push({ market: item.market, odd, probability: pct, rank: ranks[item.market] ?? 9, bookmaker: item.bookmaker,
      // Ham maç önü fiyatlarını sonuç analizi için sakla; arayüz bunları göstermiyor.
      overOdd: item.over, underOdd: item.under, yesOdd: item.yes, noOdd: item.no,
      homeOdd: item.market === "MS 1" ? item.home : null, drawOdd: item.market === "MS 1" ? item.draw : null,
      awayOdd: item.market === "MS 1" ? item.away : null, outcomeProbabilities });
  }
  // If API-Football has multiple bookmakers, keep each book's pair intact and prefer Bet365 only as a tie-break.
  return candidates.sort((a,b) => (/bet365/i.test(b.bookmaker)-/bet365/i.test(a.bookmaker)) || b.probability-a.probability || a.rank-b.rank);
}

function teamGoalAlternative(fixture, forms, stats, liveOddsRow, prematchOddsRow) {
  if (!stats?.available || !forms?.home?.available || !forms?.away?.available) return null;
  const preferredOdds = liveOddsRow && (liveOddsRow.response || []).length ? liveOddsRow : prematchOddsRow;
  let homeAhOdd = null, awayAhOdd = null, oddsSource = null;
  for (const book of bookmakerRows(preferredOdds)) {
    for (const bet of (book.bets || [])) {
      if (!/asian handicap|handicap/.test(String(bet.name || '').toLowerCase())) continue;
      let h = null, a = null;
      for (const value of (bet.values || [])) {
        const label = String(value.value ?? value.name ?? '').toLowerCase().replace(/[−–—]/g, '-').trim();
        const odd = Number(value.odd);
        if (!Number.isFinite(odd) || odd <= 1.01) continue;
        if (/(home|team 1|^1\b)/.test(label) && /-\s*0[.,]5/.test(label)) h = odd;
        if (/(away|team 2|^2\b)/.test(label) && /\+\s*0[.,]5/.test(label)) a = odd;
        // Some feeds put the selection name and handicap in separate fields.
        if (/(home|team 1|^1\b)/.test(label) && /0[.,]5/.test(label) && !/[+-]\s*0[.,]5/.test(label)) h = odd;
        if (/(away|team 2|^2\b)/.test(label) && /0[.,]5/.test(label) && !/[+-]\s*0[.,]5/.test(label)) a = odd;
      }
      if (h && a) { homeAhOdd = h; awayAhOdd = a; oddsSource = book.name || 'API-Football'; break; }
    }
    if (homeAhOdd && awayAhOdd) break;
  }
  const sidePressure = side => {
    const x = stats[side] || {};
    return Number(x.shotsOnTarget || 0) * 2.5 + Number(x.totalShots || 0) * 0.45 + Number(x.corners || 0) * 0.8;
  };
  const homePressure = sidePressure('home'), awayPressure = sidePressure('away');
  // Alternative market is EV/DEP 1.5 ÜST, so rank direction using each team's 1.5+ goal form first.
  const homeFormPct = Number(forms.home.teamGoalsOver15Pct ?? forms.home.teamGoalsOver05Pct ?? 0);
  const awayFormPct = Number(forms.away.teamGoalsOver15Pct ?? forms.away.teamGoalsOver05Pct ?? 0);
  let homeOddsPct = null, awayOddsPct = null;
  if (homeAhOdd && awayAhOdd) {
    const hi = 1 / homeAhOdd, ai = 1 / awayAhOdd, sum = hi + ai;
    homeOddsPct = 100 * hi / sum; awayOddsPct = 100 * ai / sum;
  }
  // Team statistics are mandatory; odds and last-five scoring form confirm rather than invent the side.
  let homeScore = homePressure * 0.45 + homeFormPct * 0.25;
  let awayScore = awayPressure * 0.45 + awayFormPct * 0.25;
  if (homeOddsPct != null && awayOddsPct != null) {
    homeScore += homeOddsPct * 0.30;
    awayScore += awayOddsPct * 0.30;
  }
  if (Math.abs(homeScore - awayScore) < 2.0) return {
    market: null, pressureSide: 'Dengeli', basis: `Takım baskısı yakın; ev ${homePressure.toFixed(1)} / dep ${awayPressure.toFixed(1)}${homeOddsPct == null ? '' : `; AH -0.5 yönü ${homeOddsPct >= awayOddsPct ? 'ev' : 'dep'}`}`
  };
  const currentHomeGoals = Number(fixture.homeScore || 0), currentAwayGoals = Number(fixture.awayScore || 0);
  if (currentHomeGoals >= 1 && currentAwayGoals >= 1) return null; // both team 0.5 markets already settled
  const side = currentHomeGoals >= 1 ? 'away' : currentAwayGoals >= 1 ? 'home' : (homeScore > awayScore ? 'home' : 'away');
  // If the selected team's 2+ goals are already scored, its 1.5+ market is settled.
  if ((side === 'home' ? currentHomeGoals : currentAwayGoals) >= 2) return null;
  const sideName = side === 'home' ? fixture.home : fixture.away;
  const market = side === 'home' ? 'EV 1.5 ÜST' : 'DEP 1.5 ÜST';
  const basisParts = [`takım baskısı ev ${homePressure.toFixed(1)} / dep ${awayPressure.toFixed(1)}`, `son 5 maç gol yüzdesi ev %${homeFormPct} / dep %${awayFormPct}`];
  if (homeOddsPct != null) basisParts.push(`AH -0.5 yönü ${homeOddsPct >= awayOddsPct ? 'ev sahibi' : 'deplasman'} (${oddsSource})`);
  else basisParts.push('AH -0.5 oranı bulunamadı; istatistik + form yönü');
  return { market, pressureSide: side === 'home' ? 'Ev sahibi' : 'Deplasman', pressureTeam: sideName, basis: basisParts.join('; ') };
}

function marketSupport(market, homeForm, awayForm) {
  if (!homeForm?.available || !awayForm?.available) return null;
  const avg = (a,b) => a == null || b == null ? null : (Number(a)+Number(b))/2;
  if (market === "EV 0.5 ÜST") return 0.65*Number(homeForm.teamGoalsOver05Pct ?? 0) + 0.35*Number(awayForm.goalsConcededPct ?? 0);
  if (market === "DEP 0.5 ÜST") return 0.65*Number(awayForm.teamGoalsOver05Pct ?? 0) + 0.35*Number(homeForm.goalsConcededPct ?? 0);
  if (market === "EV 1.5 ÜST") return 0.65*Number(homeForm.teamGoalsOver15Pct ?? 0) + 0.35*Number(awayForm.goalsConcededPct ?? 0);
  if (market === "DEP 1.5 ÜST") return 0.65*Number(awayForm.teamGoalsOver15Pct ?? 0) + 0.35*Number(homeForm.goalsConcededPct ?? 0);
  if (market === "MS 2.5 ÜST") return avg(homeForm.over25Pct, awayForm.over25Pct);
  if (market === "MS 3.5 ÜST") return avg(homeForm.over35Pct, awayForm.over35Pct);
  if (market === "MS 1.5 ÜST") return avg(homeForm.over15Pct, awayForm.over15Pct);
  if (market === "MS 0.5 ÜST") return avg(homeForm.over05Pct, awayForm.over05Pct);
  if (market === "KG VAR") return avg(homeForm.bttsPct, awayForm.bttsPct);
  if (market === "İY 0.5 ÜST") {
    const h5=Number(homeForm.htOver05Pct5 ?? homeForm.htOver05Pct), a5=Number(awayForm.htOver05Pct5 ?? awayForm.htOver05Pct);
    const h10=Number(homeForm.htOver05Pct10 ?? h5), a10=Number(awayForm.htOver05Pct10 ?? a5);
    if (![h5,a5,h10,a10].every(Number.isFinite)) return null;
    return 0.60*((h5+a5)/2)+0.40*((h10+a10)/2);
  }
  if (market === "İY 1.5 ÜST") {
    const h5=Number(homeForm.htOver15Pct5 ?? homeForm.htOver15Pct), a5=Number(awayForm.htOver15Pct5 ?? awayForm.htOver15Pct);
    const h10=Number(homeForm.htOver15Pct10 ?? h5), a10=Number(awayForm.htOver15Pct10 ?? a5);
    if (![h5,a5,h10,a10].every(Number.isFinite)) return null;
    return 0.60*((h5+a5)/2)+0.40*((h10+a10)/2);
  }
  return null;
}

async function fetchTeamSeasonGoals(teamId, leagueId, season, venue) {
  if (!teamId || !leagueId || !season || !['home', 'away'].includes(venue)) return null;
  try {
    // Team-season stats change slowly; cache them for 12 hours to conserve API quota.
    const payload = await cachedProviderRequest(
      `team-season:${teamId}:${leagueId}:${season}`,
      `/teams/statistics?team=${encodeURIComponent(teamId)}&league=${encodeURIComponent(leagueId)}&season=${encodeURIComponent(season)}`,
      12 * 60 * 60 * 1000
    );
    const data = payload.response || {};
    const played = Number(data.fixtures?.played?.[venue] || 0);
    const avgFor = Number(data.goals?.for?.average?.[venue]);
    const avgAgainst = Number(data.goals?.against?.average?.[venue]);
    if (played < 5 || !Number.isFinite(avgFor) || !Number.isFinite(avgAgainst)) return null;
    return { played, avgGoalsFor: avgFor, avgGoalsAgainst: avgAgainst };
  } catch (e) {
    // Season stats are supplementary: an endpoint failure must not break the existing form analysis.
    console.warn(`[Team season stats] team=${teamId} league=${leagueId} season=${season}: ${e.message}`);
    return null;
  }
}

async function fetchTeamRecentForm(teamId, fixtureId, leagueId = null, season = null, venue = null) {
  if (!teamId) return { available: false, sampleSize: 0 };
  try {
    const payload = await cachedProviderRequest(`form:${teamId}`, `/fixtures?team=${teamId}&last=10`, 6 * 60 * 60 * 1000);
    const rows = (payload.response || []).filter(row => Number(row.fixture?.id) !== Number(fixtureId) &&
      ["FT", "AET", "PEN"].includes(String(row.fixture?.status?.short || "").toUpperCase()) &&
      row.goals?.home != null && row.goals?.away != null)
      .sort((a,b) => new Date(b.fixture?.date || 0) - new Date(a.fixture?.date || 0)).slice(0,10);
    if (rows.length < 5) return { available: false, sampleSize: rows.length };
    const recent5Rows = rows.slice(0,5);
    const pct = fn => Math.round(100 * vals.filter(fn).length / vals.length);
    const vals = recent5Rows.map(r => {
      const isHome = Number(r.teams?.home?.id) === Number(teamId);
      const gf = Number(isHome ? r.goals.home : r.goals.away);
      const ga = Number(isHome ? r.goals.away : r.goals.home);
      const total = Number(r.goals.home) + Number(r.goals.away);
      const hth = r.score?.halftime?.home, hta = r.score?.halftime?.away;
      const htFor = hth == null || hta == null ? null : Number(isHome ? hth : hta);
      const htAgainst = hth == null || hta == null ? null : Number(isHome ? hta : hth);
      return { gf, ga, total, btts: Number(r.goals.home)>0 && Number(r.goals.away)>0,
        htFor, htAgainst,
        htTotal: hth == null || hta == null ? null : Number(hth)+Number(hta) };
    });
    const htVals = vals.filter(x => x.htTotal != null);
    const vals10 = rows.map(r => {
      const isHome = Number(r.teams?.home?.id) === Number(teamId);
      const hth = r.score?.halftime?.home, hta = r.score?.halftime?.away;
      return { htTotal: hth == null || hta == null ? null : Number(hth)+Number(hta) };
    });
    const htVals10 = vals10.filter(x => x.htTotal != null);
    const recentAvgGoalsFor = Number((vals.reduce((sum,x)=>sum+x.gf,0)/vals.length).toFixed(2));
    const recentAvgGoalsAgainst = Number((vals.reduce((sum,x)=>sum+x.ga,0)/vals.length).toFixed(2));
    const seasonStats = await fetchTeamSeasonGoals(teamId, leagueId, season, venue);
    // Blend the recent five-match form with the team's home/away season rate.
    // Recent form carries more weight (70%) so the season average stabilizes rather than overrides it.
    const blend = (recent, seasonal) => seasonal == null ? recent : Number((recent * 0.70 + seasonal * 0.30).toFixed(2));
    return {
      available: true, sampleSize: rows.length,
      teamGoalsOver05Pct: pct(x => x.gf >= 1),
      teamGoalsOver15Pct: pct(x => x.gf >= 2),
      goalsConcededPct: pct(x => x.ga > 0),
      over05Pct: pct(x => x.total >= 1), over15Pct: pct(x => x.total >= 2),
      over25Pct: pct(x => x.total >= 3), over35Pct: pct(x => x.total >= 4),
      bttsPct: pct(x => x.btts),
      htOver05Pct: htVals.length ? Math.round(100 * htVals.filter(x=>x.htTotal>=1).length / htVals.length) : null,
      htOver15Pct: htVals.length ? Math.round(100 * htVals.filter(x=>x.htTotal>=2).length / htVals.length) : null,
      htOver05Pct5: htVals.length ? Math.round(100 * htVals.filter(x=>x.htTotal>=1).length / htVals.length) : null,
      htOver15Pct5: htVals.length ? Math.round(100 * htVals.filter(x=>x.htTotal>=2).length / htVals.length) : null,
      htOver05Pct10: htVals10.length ? Math.round(100 * htVals10.filter(x=>x.htTotal>=1).length / htVals10.length) : null,
      htOver15Pct10: htVals10.length ? Math.round(100 * htVals10.filter(x=>x.htTotal>=2).length / htVals10.length) : null,
      htSampleSize5: htVals.length,
      htSampleSize10: htVals10.length,
      htAvgGoalsFor: htVals.length ? Number((htVals.reduce((sum,x)=>sum+x.htFor,0)/htVals.length).toFixed(2)) : null,
      htAvgGoalsAgainst: htVals.length ? Number((htVals.reduce((sum,x)=>sum+x.htAgainst,0)/htVals.length).toFixed(2)) : null,
      htSampleSize: htVals.length,
      avgGoalsFor: blend(recentAvgGoalsFor, seasonStats?.avgGoalsFor),
      avgGoalsAgainst: blend(recentAvgGoalsAgainst, seasonStats?.avgGoalsAgainst),
      recentAvgGoalsFor, recentAvgGoalsAgainst,
      seasonAvgGoalsFor: seasonStats?.avgGoalsFor ?? null,
      seasonAvgGoalsAgainst: seasonStats?.avgGoalsAgainst ?? null,
      seasonMatches: seasonStats?.played ?? null,
      matches: rows.map(r=>({score:`${r.goals.home}-${r.goals.away}`, halftimeScore:r.score?.halftime?.home==null?null:`${r.score.halftime.home}-${r.score.halftime.away}`}))
    };
  } catch (e) {
    console.warn(`[Team form] team=${teamId}: ${e.message}`);
    return { available: false, sampleSize: 0 };
  }
}


// LIVE-ONLY goal profile: last 10 completed matches are the base sample;
// last 5 are retained separately as a recent-form signal. This deliberately
// does not change the shared prematch analysis/form functions.
async function fetchLiveGoalProfile(teamId, fixtureId) {
  if (!teamId) return { available: false, sampleSize: 0, recentSampleSize: 0 };
  try {
    const payload = await cachedProviderRequest(
      `live-goal-profile:${teamId}`,
      `/fixtures?team=${encodeURIComponent(teamId)}&last=10`,
      6 * 60 * 60 * 1000
    );
    const rows = (payload.response || [])
      .filter(row => Number(row.fixture?.id) !== Number(fixtureId) &&
        ["FT", "AET", "PEN"].includes(String(row.fixture?.status?.short || "").toUpperCase()) &&
        row.goals?.home != null && row.goals?.away != null)
      .sort((a,b) => new Date(b.fixture?.date || 0) - new Date(a.fixture?.date || 0))
      .slice(0,10);
    const toMetrics = sample => {
      const vals = sample.map(row => {
        const isHome = Number(row.teams?.home?.id) === Number(teamId);
        const gf = Number(isHome ? row.goals.home : row.goals.away);
        const ga = Number(isHome ? row.goals.away : row.goals.home);
        const htH = row.score?.halftime?.home, htA = row.score?.halftime?.away;
        const htFor = htH == null || htA == null ? null : Number(isHome ? htH : htA);
        const htAgainst = htH == null || htA == null ? null : Number(isHome ? htA : htH);
        const htTotal = htH == null || htA == null ? null : Number(htH) + Number(htA);
        return { gf, ga, btts: Number(row.goals.home)>0 && Number(row.goals.away)>0,
          htFor, htAgainst, htTotal };
      });
      const pct = fn => vals.length ? Math.round(100 * vals.filter(fn).length / vals.length) : null;
      const ht = vals.filter(x => x.htTotal != null);
      const htPct = fn => ht.length ? Math.round(100 * ht.filter(fn).length / ht.length) : null;
      return {
        sampleSize: vals.length,
        teamScoredPct: pct(x => x.gf >= 1),
        teamScored2PlusPct: pct(x => x.gf >= 2),
        teamConcededPct: pct(x => x.ga >= 1),
        over15Pct: pct(x => x.gf + x.ga >= 2),
        over25Pct: pct(x => x.gf + x.ga >= 3),
        bttsPct: pct(x => x.btts),
        htSampleSize: ht.length,
        htOver05Pct: htPct(x => x.htTotal >= 1),
        htOver15Pct: htPct(x => x.htTotal >= 2),
        htBttsPct: htPct(x => x.htFor >= 1 && x.htAgainst >= 1),
        htTeamScoredPct: htPct(x => x.htFor >= 1),
        avgGoalsFor: vals.length ? Number((vals.reduce((s,x)=>s+x.gf,0)/vals.length).toFixed(2)) : null,
        avgGoalsAgainst: vals.length ? Number((vals.reduce((s,x)=>s+x.ga,0)/vals.length).toFixed(2)) : null,
        htAvgGoalsFor: ht.length ? Number((ht.reduce((s,x)=>s+x.htFor,0)/ht.length).toFixed(2)) : null
      };
    };
    const base = toMetrics(rows);
    const recent = toMetrics(rows.slice(0,5));
    return { available: rows.length >= 5, ...base, recentSampleSize: recent.sampleSize, recent };
  } catch (error) {
    console.warn(`[Live goal profile] team=${teamId}: ${error.message}`);
    return { available: false, sampleSize: 0, recentSampleSize: 0 };
  }
}

function liveStatsMetrics(stats, fixture) {
  const out = { available: false, shotsOnTarget: 0, totalShots: 0, corners: 0,
    home: { shotsOnTarget: 0, totalShots: 0, corners: 0 }, away: { shotsOnTarget: 0, totalShots: 0, corners: 0 } };
  const seen = { home: new Set(), away: new Set() };
  for (const team of (Array.isArray(stats) ? stats : [])) {
    const teamId = Number(team.team?.id);
    const side = teamId === Number(fixture.homeId) ? "home" : teamId === Number(fixture.awayId) ? "away" : null;
    if (!side) continue;
    for (const st of (team.statistics || [])) {
      const type = String(st.type || "").toLowerCase();
      if (st.value == null || String(st.value).trim() === "" || /^[-—]+$/.test(String(st.value).trim())) continue;
      const value = Number(String(st.value).replace('%',''));
      if (!Number.isFinite(value)) continue;
      if (/shots on goal|shots on target/.test(type)) { out.shotsOnTarget += value; out[side].shotsOnTarget += value; seen[side].add("shotsOnTarget"); }
      else if (/total shots|goal attempts/.test(type)) { out.totalShots += value; out[side].totalShots += value; seen[side].add("totalShots"); }
      else if (/corner kicks|corners/.test(type)) { out.corners += value; out[side].corners += value; seen[side].add("corners"); }
    }
  }
  // A two-row response alone is not proof that usable live stats exist.
  out.available = seen.home.size > 0 && seen.away.size > 0;
  out.pressure = out.shotsOnTarget*2.5 + out.totalShots*0.45 + out.corners*0.8;
  return out;
}

function poissonProbabilityAtLeast(threshold, lambda, currentGoals = 0) {
  const need = Number(threshold) - Number(currentGoals || 0);
  if (need <= 0) return 1;
  let cumulative = 0;
  for (let k = 0; k < need; k++) cumulative += Math.exp(-lambda) * Math.pow(lambda, k) / factorial(k);
  return Math.max(0, Math.min(1, 1 - cumulative));
}
function factorial(n) { let out = 1; for (let i = 2; i <= n; i++) out *= i; return out; }
function lambdaFromMarketProbability(probability, threshold, currentGoals = 0) {
  const p = Number(probability);
  if (!Number.isFinite(p) || p <= 0.01 || p >= 0.99 || Number(currentGoals || 0) >= Number(threshold)) return null;
  let low = 0, high = 8;
  for (let i = 0; i < 50; i++) {
    const mid = (low + high) / 2;
    if (poissonProbabilityAtLeast(threshold, mid, currentGoals) < p) low = mid;
    else high = mid;
  }
  return (low + high) / 2;
}
function marketProbabilitiesByName(oddsRow) {
  const rows = oddsForFixture(oddsRow);
  const grouped = new Map();
  for (const row of rows) {
    if (!Number.isFinite(Number(row.probability))) continue;
    if (!grouped.has(row.market)) grouped.set(row.market, []);
    grouped.get(row.market).push(row);
  }
  const result = {};
  for (const [market, values] of grouped) {
    // Bet365 varsa onu kullan; yoksa aynı pazardaki en yüksek güvenilir API olasılığını kullan.
    const preferred = values.find(value => /bet365/i.test(String(value.bookmaker || "")));
    const selected = preferred || values[0];
    result[market] = Number(selected.probability) / 100;
  }
  return result;
}
function scorePrediction(fixture, homeForm, awayForm, liveOddsRow = null, prematchOddsRow = null, preferredMarket = null) {
  // Günün Analizi skor motoru: maç önü oranları ana sinyaldir; son 5 maç
  // yalnızca gol toplamını ve takım gol dağılımını destekler. Canlı oran/skor kullanılmaz.
  const hasForm = Boolean(homeForm?.available && awayForm?.available);
  const pre = marketProbabilitiesByName(prematchOddsRow);
  const rows = oddsForFixture(prematchOddsRow);
  const outcomeRows = rows.filter(x => x.market === "MS 1" && x.outcomeProbabilities);
  const outcomeRow = outcomeRows.find(x => /bet365/i.test(String(x.bookmaker || ""))) || outcomeRows[0];
  // oddsForFixture outcomeProbabilities yüzdelik (0-100) döndürür.
  // Modelin bütün hedefleri 0-1 aralığında olduğundan burada normalize et.
  const outcomePct = outcomeRow?.outcomeProbabilities || null;
  const outcome = outcomePct ? {
    home:Number(outcomePct.home)/100,
    draw:Number(outcomePct.draw)/100,
    away:Number(outcomePct.away)/100
  } : null;

  const totalLines = [["MS 1.5 ÜST",2],["MS 2.5 ÜST",3],["MS 3.5 ÜST",4],["MS 5.5 ÜST",6]];
  const totalLambdas = totalLines.map(([market,threshold]) =>
    lambdaFromMarketProbability(pre[market],threshold,0)
  ).filter(Number.isFinite).sort((a,b)=>a-b);
  const marketTotalLambda = totalLambdas.length
    ? totalLambdas[Math.floor((totalLambdas.length-1)/2)] : null;

  const marketHomeLambda = lambdaFromMarketProbability(pre["EV 1.5 ÜST"],2,0);
  const marketAwayLambda = lambdaFromMarketProbability(pre["DEP 1.5 ÜST"],2,0);
  // V4: Ev/deplasman gol beklentilerini ayrı ayrı, aynı skor matrisi üzerinde
  // maç önü piyasalarının tamamına uydur. Önceki sürüm toplam gol + ev payı
  // şeklinde iki aşamalıydı; bu yaklaşım bazı farklı maçları aynı 1-1 skoruna
  // yığabiliyordu. Bet365 her pazarda önceliklidir.
  const formHome = hasForm
    ? Math.max(0.08,0.58*Number(homeForm.avgGoalsFor||0)+0.42*Number(awayForm.avgGoalsAgainst||0)) : null;
  const formAway = hasForm
    ? Math.max(0.08,0.58*Number(awayForm.avgGoalsFor||0)+0.42*Number(homeForm.avgGoalsAgainst||0)) : null;
  const pmf=(k,l)=>Math.exp(-l)*Math.pow(l,k)/factorial(k);
  // Conservative Dixon-Coles low-score dependence correction. The coefficient
  // remains experimental until it is fitted by league on a clean historical set.
  const dcRho=(lh,la)=>-Math.min(0.06,0.75/Math.max(0.01,lh*la));
  const dcTau=(h,a,lh,la,rho)=>{
    if(h===0&&a===0) return 1-lh*la*rho;
    if(h===0&&a===1) return 1+lh*rho;
    if(h===1&&a===0) return 1+la*rho;
    if(h===1&&a===1) return 1-rho;
    return 1;
  };
  const dcGrid=(lh,la,maxGoals=10)=>{
    const rho=dcRho(lh,la), cells=[];
    let mass=0;
    for(let h=0;h<=maxGoals;h++) for(let a=0;a<=maxGoals;a++){
      const p=Math.max(0,pmf(h,lh)*pmf(a,la)*dcTau(h,a,lh,la,rho));
      cells.push({home:h,away:a,probability:p}); mass+=p;
    }
    const norm=mass||1;
    for(const cell of cells) cell.probability/=norm;
    return cells;
  };
  const matrixStats=(lh,la)=>{
    let home=0,draw=0,away=0,over15=0,over25=0,over35=0,over55=0,btts=0,home15=0,away15=0;
    for(const cell of dcGrid(lh,la,10)){
      const {home:h,away:a,probability:p}=cell, total=h+a;
      if(h>a) home+=p; else if(h===a) draw+=p; else away+=p;
      if(total>=2) over15+=p; if(total>=3) over25+=p; if(total>=4) over35+=p; if(total>=6) over55+=p;
      if(h>0&&a>0) btts+=p; if(h>=2) home15+=p; if(a>=2) away15+=p;
    }
    return {home,draw,away,over15,over25,over35,over55,btts,home15,away15};
  };
  const targets=[];
  const addTarget=(key,target,weight)=>{
    const p=Number(target);
    if(Number.isFinite(p)&&p>=0.03&&p<=0.97) targets.push({key,p,weight});
  };
  if(outcome){
    // 1X2 piyasa yönü skor motorunun ana girdisidir. Önceki 2.2 ağırlığı,
    // gol çizgileri ve form öncülünün 1X2 favori bilgisini bastırmasına izin veriyordu.
    addTarget("home",outcome.home,5.5); addTarget("draw",outcome.draw,5.5); addTarget("away",outcome.away,5.5);
  }
  addTarget("over15",pre["MS 1.5 ÜST"],1.0);
  addTarget("over25",pre["MS 2.5 ÜST"],2.2);
  addTarget("over35",pre["MS 3.5 ÜST"],1.2);
  addTarget("over55",pre["MS 5.5 ÜST"],0.45);
  addTarget("btts",pre["KG VAR"],1.8);
  addTarget("home15",pre["EV 1.5 ÜST"],1.0);
  addTarget("away15",pre["DEP 1.5 ÜST"],1.0);

  // Takım formu veri varsa zayıf öncül olarak kullanılır; maç önü piyasa
  // olasılıkları daha yüksek ağırlıktadır.
  const priorHome=Number.isFinite(formHome)?Math.max(0.15,Math.min(3.8,formHome)):null;
  const priorAway=Number.isFinite(formAway)?Math.max(0.15,Math.min(3.8,formAway)):null;
  const lossAt=(lh,la)=>{
    const stats=matrixStats(lh,la);
    let loss=0,weight=0;
    for(const t of targets){loss+=t.weight*Math.pow(stats[t.key]-t.p,2);weight+=t.weight;}
    // Son 5 maç formu yalnızca destekleyici öncül; piyasa sinyalini geçersiz kılamaz.
    if(priorHome!=null){loss+=0.12*Math.pow(lh-priorHome,2);weight+=0.12;}
    if(priorAway!=null){loss+=0.12*Math.pow(la-priorAway,2);weight+=0.12;}
    return weight?loss/weight:Infinity;
  };
  let lambdaHome=null,lambdaAway=null,bestLoss=Infinity;
  // Kaba tarama + en iyi bölgenin hassas taraması. Her maçta iki gol
  // beklentisi ayrı optimize edilir; tek bir sabit gol paylaşımı yoktur.
  if(targets.length||priorHome!=null||priorAway!=null){
    for(let h=0.20;h<=3.8001;h+=0.10) for(let a=0.20;a<=3.8001;a+=0.10){
      const loss=lossAt(h,a);
      if(loss<bestLoss){bestLoss=loss;lambdaHome=h;lambdaAway=a;}
    }
    if(lambdaHome!=null){
      const centerH=lambdaHome,centerA=lambdaAway;
      for(let h=Math.max(0.12,centerH-0.12);h<=Math.min(4.0,centerH+0.12)+0.0001;h+=0.02)
        for(let a=Math.max(0.12,centerA-0.12);a<=Math.min(4.0,centerA+0.12)+0.0001;a+=0.02){
          const loss=lossAt(h,a);
          if(loss<bestLoss){bestLoss=loss;lambdaHome=h;lambdaAway=a;}
        }
    }
  }
  if(!Number.isFinite(lambdaHome)||!Number.isFinite(lambdaAway)) return {
    halfTimeScore:"Tahmin üretilemedi",fullTimeScore:"Tahmin üretilemedi",alternativeFullTimeScore:"Tahmin üretilemedi",
    sixPlusProbability:null,sixPlusCandidate:false,
    scoreBasis:"Maç önü oranı veya iki takımın son 5 maç gol verisi yetersiz"
  };
  lambdaHome=Math.max(0.08,Math.min(4.5,lambdaHome));
  lambdaAway=Math.max(0.08,Math.min(4.5,lambdaAway));

  const scores=dcGrid(lambdaHome,lambdaAway,10)
    .filter(x=>x.home<=9&&x.away<=9)
    .map(x=>({home:x.home,away:x.away,probability:x.probability}));
  const scoreMeetsMarket=(x,market)=>{
    const total=x.home+x.away;
    if(market==="KG VAR") return x.home>0&&x.away>0;
    if(market==="KG YOK") return x.home===0||x.away===0;
    if(market==="EV 1.5 ÜST") return x.home>=2;
    if(market==="DEP 1.5 ÜST") return x.away>=2;
    if(market==="MS 0.5 ÜST") return total>=1;
    if(market==="MS 1.5 ÜST") return total>=2;
    if(market==="MS 2.5 ÜST") return total>=3;
    if(market==="MS 3.5 ÜST") return total>=4;
    return true;
  };
  // İki ayrı skor sıralaması tutulur:
  // 1) Koşulsuz skor: maçın genel olarak en olası gerçek skoru.
  // 2) Pazar senaryosu: seçilen KG/ÜST tercihi gerçekleşirse en olası skor.
  // Pazar koşuluna göre normalize edilmiş yüzde, genel skor olasılığı gibi sunulmaz.
  const unconditionalScores = scores.map(x => ({...x}));
  unconditionalScores.sort((a,b)=>
    b.probability-a.probability ||
    (a.home+a.away)-(b.home+b.away) ||
    b.home-a.home
  );
  const unconditionalBest = unconditionalScores[0];
  const unconditionalAlternative = unconditionalScores[1] || unconditionalBest;

  const conditionalScores=preferredMarket
    ? scores.filter(x=>scoreMeetsMarket(x,preferredMarket))
    : scores;
  const scenarioScores=(conditionalScores.length?conditionalScores:scores).map(x=>({...x}));
  const scenarioMass=scenarioScores.reduce((sum,x)=>sum+x.probability,0)||1;
  for(const x of scenarioScores)x.probability/=scenarioMass;
  scenarioScores.sort((a,b)=>
    b.probability-a.probability ||
    (a.home+a.away)-(b.home+b.away) ||
    b.home-a.home
  );
  let marketScenarioBest=scenarioScores[0];
  // 1X2 yönü yalnızca pazar senaryosunda çok yakın olasılıklarda bağlayıcıdır.
  if(outcome){
    const favorite=outcome.home>outcome.away?"home":outcome.away>outcome.home?"away":null;
    if(favorite){
      const favoriteCandidate=scenarioScores.find(x=>
        favorite==="home"?x.home>x.away:x.away>x.home
      );
      if(favoriteCandidate && favoriteCandidate.probability>=marketScenarioBest.probability*0.92)
        marketScenarioBest=favoriteCandidate;
    }
  }
  const marketScenarioAlternative=
    scenarioScores.find(x=>x.home!==marketScenarioBest.home||x.away!==marketScenarioBest.away)
    || unconditionalAlternative;
  const best=unconditionalBest;
  const alternative=unconditionalAlternative;
  const sixPlusProbability=scores.reduce((sum,x)=>sum+(x.home+x.away>=6?x.probability:0),0);
  const sixPlusCandidate=sixPlusProbability>=0.20;
  const constraints=targets;

  // İlk yarı modeli: önce maç önü İY gol çizgileri, yoksa son 5 maçın
  // gerçek devre arası gol frekansları kullanılır. Sabit %44 varsayımı artık
  // tek başına kullanılmaz; yalnızca veri yoksa emniyetli yedek olarak kalır.
  const ht05=pre["İY 0.5 ÜST"], ht15=pre["İY 1.5 ÜST"];
  const fitLambdaFromRates = (p05, p15) => {
    if (!Number.isFinite(p05) && !Number.isFinite(p15)) return null;
    let bestLambda=null, bestError=Infinity;
    for(let l=0.05;l<=4.00;l+=0.005){
      let error=0, count=0;
      if(Number.isFinite(p05)){ error+=Math.pow(poissonProbabilityAtLeast(1,l,0)-p05,2); count++; }
      if(Number.isFinite(p15)){ error+=Math.pow(poissonProbabilityAtLeast(2,l,0)-p15,2); count++; }
      if(count && error/count<bestError){bestError=error/count;bestLambda=l;}
    }
    return bestLambda;
  };
  const marketHtLambda=fitLambdaFromRates(ht05,ht15);
  const formHt05Vals=[homeForm?.htOver05Pct,awayForm?.htOver05Pct]
    .filter(Number.isFinite).map(x=>Number(x)/100);
  const formHt15Vals=[homeForm?.htOver15Pct,awayForm?.htOver15Pct]
    .filter(Number.isFinite).map(x=>Number(x)/100);
  const formHt05=formHt05Vals.length ? formHt05Vals.reduce((a,b)=>a+b,0)/formHt05Vals.length : null;
  const formHt15=formHt15Vals.length ? formHt15Vals.reduce((a,b)=>a+b,0)/formHt15Vals.length : null;
  const formHtLambda=fitLambdaFromRates(formHt05,formHt15);
  let htTotal=null, halfTimeBasis="yedek %44 tam maç gol payı";
  if(Number.isFinite(marketHtLambda) && Number.isFinite(formHtLambda)){
    htTotal=0.65*marketHtLambda+0.35*formHtLambda;
    halfTimeBasis="maç önü İY gol oranları + son 5 maç devre arası gol frekansı";
  } else if(Number.isFinite(marketHtLambda)){
    htTotal=marketHtLambda;
    halfTimeBasis="maç önü İY gol oranları";
  } else if(Number.isFinite(formHtLambda)){
    htTotal=0.75*formHtLambda+0.25*0.44*(lambdaHome+lambdaAway);
    halfTimeBasis="son 5 maç devre arası gol frekansı + tam maç beklentisi";
  } else {
    htTotal=0.44*(lambdaHome+lambdaAway);
  }
  htTotal=Math.max(0.05,Math.min(lambdaHome+lambdaAway,htTotal));
  const htHomeForm = Number.isFinite(homeForm?.htAvgGoalsFor) && Number.isFinite(awayForm?.htAvgGoalsAgainst)
    ? Math.max(0.03,0.55*Number(homeForm.htAvgGoalsFor)+0.45*Number(awayForm.htAvgGoalsAgainst)) : null;
  const htAwayForm = Number.isFinite(awayForm?.htAvgGoalsFor) && Number.isFinite(homeForm?.htAvgGoalsAgainst)
    ? Math.max(0.03,0.55*Number(awayForm.htAvgGoalsFor)+0.45*Number(homeForm.htAvgGoalsAgainst)) : null;
  const htTeamFormAvailable = htHomeForm != null && htAwayForm != null;
  const ftShare = lambdaHome/(lambdaHome+lambdaAway);
  let htShare=ftShare;
  if(htTeamFormAvailable && (htHomeForm+htAwayForm)>0){
    const formShare=htHomeForm/(htHomeForm+htAwayForm);
    htShare=0.65*formShare+0.35*ftShare;
  }
  const htHome=htTotal*htShare, htAway=htTotal*(1-htShare);
  const htScores=dcGrid(htHome,htAway,6)
    .filter(x=>x.home<=5&&x.away<=5)
    .map(x=>({home:x.home,away:x.away,p:x.probability}));
  htScores.sort((a,b)=>b.p-a.p||(a.home+a.away)-(b.home+b.away)||b.home-a.home);
  if(htTeamFormAvailable) halfTimeBasis += " + takım bazında son 5 İY golü";

  const basis=[];
  if(outcome) basis.push("Bet365 öncelikli, marjı ayıklanmış maç önü 1X2 güç dağılımı");
  if(marketTotalLambda!=null) basis.push("maç önü toplam gol çizgileri");
  if(marketHomeLambda!=null||marketAwayLambda!=null) basis.push("takım gol çizgileri");
  if(hasForm) basis.push("son 5 maç hücum/savunma desteği");
  if(constraints.length) basis.push("gol/KG/1X2 olasılıklarıyla ortak skor matrisi");
  if(Number.isFinite(ht05)||Number.isFinite(ht15)||Number.isFinite(formHtLambda)) basis.push(halfTimeBasis);
  return {
    halfTimeScore:`${htScores[0].home}-${htScores[0].away} (tahmin)`,
    // Kesin skor tahmini, seçilen bahis pazarına göre koşullandırılmaz.
    // Aksi halde KG VAR seçildiğinde 1-1 gibi skorlar yapay biçimde öne çıkar.
    // Pazar gerçekleşirse en olası skorlar aşağıdaki marketScenario alanlarında ayrı tutulur.
    fullTimeScore:`${best.home}-${best.away} (tahmin)`,
    alternativeFullTimeScore:`${alternative.home}-${alternative.away} (alternatif tahmin)`,
    unconditionalFullTimeScore:`${best.home}-${best.away}`,
    unconditionalAlternativeFullTimeScore:`${alternative.home}-${alternative.away}`,
    predictedScoreProbability:Number(best.probability.toFixed(4)),
    sixPlusProbability:Number(sixPlusProbability.toFixed(4)),
    sixPlusCandidate,
    marketScenarioScore:`${marketScenarioBest.home}-${marketScenarioBest.away} (tercih senaryosu)`,
    marketScenarioAlternativeScore:`${marketScenarioAlternative.home}-${marketScenarioAlternative.away} (tercih senaryosu alternatifi)`,
    scoreBasis:basis.join(" + ")||"Maç önü oranları ve son 5 maç formu",
    expectedGoals:{home:Number(lambdaHome.toFixed(2)),away:Number(lambdaAway.toFixed(2))},
    expectedHalfTimeGoals:{home:Number(htHome.toFixed(2)),away:Number(htAway.toFixed(2)),total:Number(htTotal.toFixed(2))},
    halfTimeBasis,
    topScoreCandidates:unconditionalScores.slice(0,3).map(x=>({
      score:`${x.home}-${x.away}`,
      probability:Number(x.probability.toFixed(4))
    })),
    marketScenarioCandidates:scenarioScores.slice(0,3).map(x=>({
      score:`${x.home}-${x.away}`,
      conditionalProbability:Number(x.probability.toFixed(4))
    })),
    scoreProbability:Number(best.probability.toFixed(4)),
    alternativeScoreProbability:Number(alternative.probability.toFixed(4)),
    marketScenarioProbability:Number(marketScenarioBest.probability.toFixed(4)),
    scoreCondition:preferredMarket || "UNCONDITIONAL",
    scoreProbabilityType:preferredMarket ? "MARKET_CONDITIONAL_FOR_PREDICTED_SCORE" : "UNCONDITIONAL",
    unconditionalScoreProbability:Number(best.probability.toFixed(4)),
    modelVersion:"V7_UNCONDITIONAL_SCORE_MARKET_SCENARIO_SPLIT",
    scoreModelMethod:"DIXON_COLES_LOW_SCORE_CORRECTION",
    dixonColesRho:Number(dcRho(lambdaHome,lambdaAway).toFixed(4)),
    htTeamFormUsed:Boolean(htTeamFormAvailable),
    htFormSampleSize:{home:Number(homeForm?.htSampleSize||0),away:Number(awayForm?.htSampleSize||0)},
    modelFitError:Number(bestLoss.toFixed(6)),
    marketTargetsUsed:targets.map(x=>x.key),
    oddsBookmaker:outcomeRow?.bookmaker || rows.find(x=>/bet365/i.test(String(x.bookmaker||"")))?.bookmaker || rows[0]?.bookmaker || null,
    market1x2:outcome?{home:Number(outcome.home.toFixed(4)),draw:Number(outcome.draw.toFixed(4)),away:Number(outcome.away.toFixed(4))}:null,
    rawOdds1x2:outcomeRow?{home:Number(outcomeRow.homeOdd),draw:Number(outcomeRow.drawOdd),away:Number(outcomeRow.awayOdd),bookmaker:outcomeRow.bookmaker}:null
  };
}

function analysisPercentages(oddsRow, homeForm, awayForm) {
  const map = { ht05: "İY 0.5 ÜST", ht15: "İY 1.5 ÜST", ms05: "MS 0.5 ÜST", ms15: "MS 1.5 ÜST", ms25: "MS 2.5 ÜST", ms35: "MS 3.5 ÜST", btts: "KG VAR", home15: "EV 1.5 ÜST", away15: "DEP 1.5 ÜST" };
  const rows = oddsForFixture(oddsRow); const out = {};
  for (const [key, market] of Object.entries(map)) {
    const o = rows.filter(x => x.market === market).sort((a,b)=>(/bet365/i.test(b.bookmaker)-/bet365/i.test(a.bookmaker)) || b.probability-a.probability)[0];
    const form = marketSupport(market, homeForm, awayForm);
    const isHalfTimeMarket = market === "İY 0.5 ÜST" || market === "İY 1.5 ÜST";
    if (isHalfTimeMarket && form != null) {
      out[key] = {
        percent: Math.round(form),
        sampleSize5: Math.min(homeForm?.htSampleSize5 || 0, awayForm?.htSampleSize5 || 0),
        sampleSize10: Math.min(homeForm?.htSampleSize10 || 0, awayForm?.htSampleSize10 || 0),
        source: "Son 5 maç İY formu (%60) + son 10 maç İY formu (%40); oran kullanılmadı"
      };
    } else if (!isHalfTimeMarket && (o || form != null)) {
      const percent = o && form != null ? Math.round(o.probability * 0.55 + form * 0.45) : o ? Math.round(o.probability) : Math.round(form);
      out[key] = { percent, sampleSize: Math.min(homeForm?.sampleSize || 0, awayForm?.sampleSize || 0), source: o && form != null ? "Maç önü oranı + son 5 maç formu" : o ? "Maç önü oranı; form verisi eksik" : "Son 5 maç formu; maç önü oranı bulunamadı" };
    }
  }
  return out;
}

function marketConsistentWithScore(market, scoreObj) {
  const pair = value => {
    const m = String(value || "").match(/(\d+)\s*[-:]\s*(\d+)/);
    return m ? [Number(m[1]), Number(m[2])] : null;
  };
  const ft = pair(scoreObj?.fullTimeScore);
  const htText = String(scoreObj?.halfTimeScore || "");
  const ht = /Canlı skor/i.test(htText) ? null : pair(htText);
  if (market === "KG VAR" && ft && (ft[0] < 1 || ft[1] < 1)) return false;
  if (market === "EV 1.5 ÜST" && ft && ft[0] < 2) return false;
  if (market === "DEP 1.5 ÜST" && ft && ft[1] < 2) return false;
  if (market === "MS 0.5 ÜST" && ft && ft[0] + ft[1] < 1) return false;
  if (market === "MS 1.5 ÜST" && ft && ft[0] + ft[1] < 2) return false;
  if (market === "MS 2.5 ÜST" && ft && ft[0] + ft[1] < 3) return false;
  if (market === "MS 3.5 ÜST" && ft && ft[0] + ft[1] < 4) return false;
  if (market === "MS 4.5 ÜST" && ft && ft[0] + ft[1] < 5) return false;
  if (market === "İY 0.5 ÜST" && ht && ht[0] + ht[1] < 1) return false;
  if (market === "İY 1.5 ÜST" && ht && ht[0] + ht[1] < 2) return false;
  return true;
}

function chooseFormFallbackMarket(mode, fixture, forms, excludeMarket = null) {
  // Fallback only when no usable market odds are available. It is explicitly labelled
  // as form-based, never presented as an odds-backed signal.
  if (!forms?.home?.available || !forms?.away?.available) return null;
  const live = mode === "live";
  const minute = Number(fixture.minute || 0);
  if (live && (minute < 20 || minute > 85)) return null;
  const total = Number(fixture.homeScore || 0) + Number(fixture.awayScore || 0);
  let allowed;
  if (!live) allowed = ["EV 1.5 ÜST", "DEP 1.5 ÜST", "MS 2.5 ÜST", "MS 3.5 ÜST", "KG VAR", "MS 1.5 ÜST"];
  else if (minute < 33) allowed = total === 0 ? ["İY 0.5 ÜST"] : ["İY 1.5 ÜST", "MS 1.5 ÜST"];
  else if (minute < 45) allowed = total === 0 ? ["MS 1.5 ÜST"] : ["MS 1.5 ÜST", "KG VAR", "MS 2.5 ÜST"];
  else if (minute < 66) allowed = total === 0 ? ["MS 1.5 ÜST"] : total === 1 ? ["MS 1.5 ÜST", "KG VAR"] : ["MS 2.5 ÜST", "KG VAR"];
  else if (minute <= 75) allowed = total <= 1 ? ["MS 1.5 ÜST", "MS 2.5 ÜST", "KG VAR"] : ["MS 2.5 ÜST", "MS 3.5 ÜST", "KG VAR"];
  else allowed = total <= 1 ? ["MS 1.5 ÜST", "MS 2.5 ÜST"] : ["MS 2.5 ÜST", "MS 3.5 ÜST"];
  const thresholds = { "EV 1.5 ÜST": 45, "DEP 1.5 ÜST": 45, "MS 0.5 ÜST": 55, "MS 1.5 ÜST": 50, "MS 2.5 ÜST": 48, "MS 3.5 ÜST": 34, "KG VAR": 48, "İY 0.5 ÜST": 52, "İY 1.5 ÜST": 34 };
  const scoreObj = scorePrediction(fixture, forms.home, forms.away, null, null);
  const candidates = allowed.filter(m => m !== excludeMarket && marketConsistentWithScore(m, scoreObj))
    .map(m => ({ market: m, formPct: marketSupport(m, forms.home, forms.away), bookmaker: "Son 5 maç formu (oran bulunamadı)", oddsTiming: "form-fallback", probability: null }))
    .filter(x => x.formPct != null && x.formPct >= (thresholds[x.market] ?? 50))
    .sort((a,b) => b.formPct - a.formPct);
  return candidates[0] || null;
}

function liveMarketAlreadySettled(market, fixture) {
  const home = Number(fixture.homeScore || 0), away = Number(fixture.awayScore || 0), total = home + away;
  const minute = Number(fixture.minute || 0);
  if (market === "KG VAR" && home > 0 && away > 0) return true;
  if (market === "İY KG VAR") {
    const phase = String(fixture.periodStatus || "").toUpperCase();
    if (["HT", "2H", "ET", "FT", "AET", "PEN"].includes(phase)) return true;
    const hg = Number(fixture.htHomeScore ?? home), ag = Number(fixture.htAwayScore ?? away);
    if (hg > 0 && ag > 0) return true;
  }
  if ((market === "EV 0.5 ÜST" || market === "EV 1.5 ÜST") && home >= (market.includes("1.5") ? 2 : 1)) return true;
  if ((market === "DEP 0.5 ÜST" || market === "DEP 1.5 ÜST") && away >= (market.includes("1.5") ? 2 : 1)) return true;
  const ms = market.match(/^MS ([0-9]+[.,][0-9]+) ÜST$/);
  if (ms && total >= Math.ceil(Number(ms[1].replace(",", ".")))) return true;
  const ht = market.match(/^İY ([0-9]+[.,][0-9]+) ÜST$/);
  if (ht) {
    const phase = String(fixture.periodStatus || "").toUpperCase();
    if (["HT", "2H", "ET", "FT", "AET", "PEN"].includes(phase)) return true;
    if (!phase && minute >= 45) return true;
    const hg = Number(fixture.htHomeScore ?? home), ag = Number(fixture.htAwayScore ?? away);
    if (hg + ag >= Math.ceil(Number(ht[1].replace(",", ".")))) return true;
  }
  return false;
}

function chooseSupportedMarket(oddsRow, mode, fixture, forms, stats, prematchOddsRow, excludeMarket = null, preferredMarket = null) {
  const live = mode === "live";
  const total = Number(fixture.homeScore || 0) + Number(fixture.awayScore || 0);
  const minute = Number(fixture.minute || 0);
  const periodStatus = String(fixture.periodStatus || fixture.status || "").toUpperCase();
  const firstHalfLive = live && periodStatus === "1H" && minute >= 10 && minute <= 45;
  // Canlı tercih: ilk yarıda 10–45 yalnızca 1H durumunda; ikinci yarıda 20–85.
  // Devre arası (HT) ve maç sonu için İY marketleri kesinlikle açılmaz.
  if (live && !firstHalfLive && (minute < 20 || minute > 85)) return null;

  // Dakika + dönem + anlık skora göre izin verilen piyasalar.
  let allowed;
  if (!live) {
    allowed = ["EV 1.5 ÜST", "DEP 1.5 ÜST", "MS 2.5 ÜST", "MS 3.5 ÜST", "KG VAR"];
  } else if (firstHalfLive && minute >= 10 && minute <= 32) {
    // 10–32: 0-0 ise İY 0.5; en az bir gol varsa takım bağımsız İY 1.5 değerlendirilir.
    if (total === 0) allowed = ["İY 0.5 ÜST"];
    else allowed = ["İY 1.5 ÜST"];
  } else if (firstHalfLive && minute >= 33 && minute <= 45) {
    // 33–45+: ilk yarı golü için daha güçlü baskı ve olasılık gerekir.
    if (total === 0) allowed = ["İY 0.5 ÜST"];
    else allowed = ["İY 1.5 ÜST"];
  } else if (minute >= 45 && minute < 60) {
    // 45–59: 0-0 ise genel MS 0.5 yerine, canlı verisi destekleyen takımın EV/DEP 0.5 pazarı seçilir.
    if (total === 0) allowed = ["EV 0.5 ÜST", "DEP 0.5 ÜST"];
    else if (total === 1) allowed = ["KG VAR"];
    else if (total === 2) allowed = ["KG VAR", "MS 2.5 ÜST"];
    else allowed = ["MS 3.5 ÜST", "KG VAR"];
  } else if (minute >= 60 && minute <= 65) {
    // 60–65: 0-0 iken takım bazlı 0.5 üst; 66. dakikadan sonra toplam gol çizgileri.
    if (total === 0) allowed = ["EV 0.5 ÜST", "DEP 0.5 ÜST"];
    else if (total === 1) allowed = ["MS 1.5 ÜST", "KG VAR"];
    else if (total === 2) allowed = ["MS 2.5 ÜST", "KG VAR"];
    else allowed = ["MS 3.5 ÜST"];
  } else if (minute >= 66 && minute <= 70) {
    // 66–70: 0-0 ise kalan süre ve toplam baskıya göre MS 0.5 değerlendirilebilir.
    if (total === 0) allowed = ["MS 0.5 ÜST"];
    else if (total === 1) allowed = ["MS 1.5 ÜST", "KG VAR"];
    else if (total === 2) allowed = ["MS 2.5 ÜST", "KG VAR"];
    else allowed = ["MS 3.5 ÜST"];
  } else if (minute >= 71 && minute <= 75) {
    // 71–75: daha fazla gol isteyen pazarlar için daha güçlü baskı aranır.
    if (total === 0) allowed = ["MS 0.5 ÜST"];
    else if (total === 1) allowed = ["MS 1.5 ÜST"];
    else if (total === 2) allowed = ["MS 2.5 ÜST", "KG VAR"];
    else allowed = ["MS 3.5 ÜST"];
  } else {
    // 76–85: MS 0.5 ÜST is only available after 65'; pressure/value checks still apply.
    if (total === 0) allowed = ["MS 0.5 ÜST", "MS 1.5 ÜST"];
    else if (total === 1) allowed = ["MS 1.5 ÜST", "MS 2.5 ÜST"];
    else if (total === 2) allowed = ["MS 2.5 ÜST", "MS 3.5 ÜST"];
    else allowed = ["MS 3.5 ÜST"];
  }

  const h = forms.home, a = forms.away;
  // Canlı maçta gerçek canlı oran önceliklidir. İlk yarıda takım bağımsız İY gol marketleri değerlendirilir.
  // Kaynak oddsTiming ile etiketlenir; ham oranlar kullanıcıya gösterilmez.
  const liveMarketRows = live ? oddsForFixture(oddsRow || null) : [];
  const preMarkets = oddsForFixture(prematchOddsRow || (!live ? oddsRow : null) || null);
  // Initialize before scorePrediction reads it; otherwise live analysis throws a TDZ error.
  const useLiveOdds = live && liveMarketRows.length > 0;
  const predictedScores = scorePrediction(fixture, h, a, useLiveOdds ? oddsRow : null, prematchOddsRow || (!live ? oddsRow : null) || null);
  const liveAllowedRows = liveMarketRows.filter(x => allowed.includes(x.market));
  const mergedMarketRows = live
    ? liveAllowedRows.map(x => ({ ...x, oddsTiming: "live" }))
    : preMarkets.map(x => ({ ...x, oddsTiming: "prematch" }));
  // Maç önü KG VAR fiyatını hem maç önü hem canlı KG VAR kararında kontrol et.
  // Aynı bookmaker'dan gelen MS 1X2 oranlarında aşırı favori farkını da tespit et.
  const prematchBttsInRange = preMarkets.some(x =>
    x.market === "KG VAR" && Number(x.odd) >= 1.50 && Number(x.odd) <= 1.73
  );
  const hasExtremeFavoriteGap = preMarkets.some(x =>
    x.market === "MS 1" && Number.isFinite(Number(x.homeOdd)) && Number.isFinite(Number(x.awayOdd)) &&
    ((Number(x.homeOdd) < 1.30 && Number(x.awayOdd) > 7.00) ||
     (Number(x.awayOdd) < 1.30 && Number(x.homeOdd) > 7.00))
  );
  const choices = mergedMarketRows.filter(x => allowed.includes(x.market) && x.market !== excludeMarket &&
    // KG VAR için gerçek maç önü fiyatı 1.50–1.73 bandında olmalı.
    !(x.market === "KG VAR" && !prematchBttsInRange) &&
    // Favori <1.30 ve rakip >7.00 ise takımlar arası güç farkı aşırı: KG VAR'ı ele.
    !(x.market === "KG VAR" && hasExtremeFavoriteGap) &&
    // Maç önü ilk yarı oranı, canlı dakikaya uygun fiyat değildir; canlı HT marketlerinde kullanma.
    !(live && x.oddsTiming !== "live" && x.market.startsWith("İY ")) &&
    (!live || !liveMarketAlreadySettled(x.market, fixture)) &&
    (live || marketConsistentWithScore(x.market, predictedScores)));
  const statsM = stats || { available: false, pressure: 0, home: {}, away: {} };
  const favorite = (() => {
    const winners = preMarkets.filter(x => x.market === "MS 1");
    const home = winners.find(x => x.bookmaker && x.market === "MS 1" && x.homeOdd)?.homeOdd;
    const away = winners.find(x => x.bookmaker && x.market === "MS 1" && x.awayOdd)?.awayOdd;
    return home && away ? (home < away ? "home" : "away") : null;
  })();
  const leader = Number(fixture.homeScore || 0) > Number(fixture.awayScore || 0) ? "home"
    : Number(fixture.awayScore || 0) > Number(fixture.homeScore || 0) ? "away" : null;

  // Canlıda biraz daha sıkı eşikler: oran olasılığı + form birlikte doğrulanmalı.
  // Daha seçici eşikler: “bankoya yakın” hedefi için piyasa ve son-5 form desteği birlikte aranır.
  // Bunlar garanti değildir; yeterli destek yoksa tercih üretilmez.
  const minMarketPct = live ? {
    "EV 0.5 ÜST": 55, "DEP 0.5 ÜST": 55, "EV 1.5 ÜST": 58, "DEP 1.5 ÜST": 58, "MS 2.5 ÜST": 58, "MS 3.5 ÜST": 48, "MS 4.5 ÜST": 38,
    "KG VAR": 58, "İY 0.5 ÜST": 52, "İY 1.5 ÜST": 48, "MS 0.5 ÜST": 58, "MS 1.5 ÜST": 58
  } : {
    "EV 0.5 ÜST": 58, "DEP 0.5 ÜST": 58, "EV 1.5 ÜST": 60, "DEP 1.5 ÜST": 60, "MS 2.5 ÜST": 58, "MS 3.5 ÜST": 50,
    "KG VAR": 58, "İY 0.5 ÜST": 56, "İY 1.5 ÜST": 48, "MS 0.5 ÜST": 64, "MS 1.5 ÜST": 60
  };
  const minFormPct = {
    "EV 0.5 ÜST": 54, "DEP 0.5 ÜST": 54, "EV 1.5 ÜST": 56, "DEP 1.5 ÜST": 56, "MS 2.5 ÜST": 56, "MS 3.5 ÜST": 48,
    "KG VAR": 56, "İY 0.5 ÜST": 50, "İY 1.5 ÜST": 46, "MS 0.5 ÜST": 54, "MS 1.5 ÜST": 54
  };

  const ranked = choices.map(choice => {
    const formPct = marketSupport(choice.market, h, a);
    let liveBonus = 0;
    let rejectReason = null;
    if (live) {
      if (!statsM.available) return null;

      // 45–65. dakikada 0-0 ise takım bazlı gol pazarı ancak o takımın kendi canlı baskısı destekliyorsa seçilir.
      if (total === 0 && minute >= 45 && minute <= 65 &&
          (choice.market === "EV 0.5 ÜST" || choice.market === "DEP 0.5 ÜST")) {
        const side = choice.market.startsWith("EV") ? (statsM.home || {}) : (statsM.away || {});
        const sideShotsOnTarget = Number(side.shotsOnTarget || 0);
        const sideShots = Number(side.totalShots || side.shots || 0);
        const sideCorners = Number(side.corners || 0);
        const sidePressure = sideShotsOnTarget * 2.5 + sideShots * 0.45 + sideCorners * 0.8;
        if (Number(choice.odd || 0) < 1.50) return null;
        if (sidePressure < 5.5 || (sideShotsOnTarget < 1 && sideShots < 5 && sideCorners < 3)) return null;
        if (Number(choice.probability || 0) < 55 || Number(formPct || 0) < 54) return null;
        liveBonus += Math.min(14, sidePressure * 0.55);
      }

      // Canlı piyasa olasılığı seçim puanında kullanılır; maç önü oranı scorePrediction içinde referans olarak kalır.

      // 40. dakikadan sonra HT üst tercihlerini kapat; kalan süre çok kısa.
      if (choice.market.startsWith("İY ") && minute >= 40) return null;
      if (choice.market.startsWith("İY ")) {
        const currentHalfGoals = Number(fixture.htHomeScore ?? fixture.homeScore ?? 0) + Number(fixture.htAwayScore ?? fixture.awayScore ?? 0);
        const line = Number(choice.market.match(/(\d)[.,](\d)/)?.[1] || 0) + 0.5;
        if (currentHalfGoals >= Math.ceil(line)) return null;
        if (minute >= 33 && (Number(statsM.pressure || 0) < 12 ||
          (Number(statsM.shotsOnTarget || 0) < 1 && Number(statsM.totalShots || 0) < 5 && Number(statsM.corners || 0) < 3))) return null;
      }
      if (choice.market === "MS 0.5 ÜST" && total >= 1) return null;
      if (choice.market === "MS 0.5 ÜST" && total === 0 && minute < 60) return null;
      if (choice.market === "MS 0.5 ÜST" && total === 0 && minute >= 66
          && choices.some(x => x.market === "MS 1.5 ÜST")
          && Number(statsM.pressure || 0) >= 10
          && (Number(statsM.shotsOnTarget || 0) >= 2 || Number(statsM.totalShots || 0) >= 8 || Number(statsM.corners || 0) >= 6)) return null;
      if (choice.market === "MS 1.5 ÜST" && total >= 2) return null;
      // 0-0 at 45–65: only allow MS 1.5 ÜST when live match activity is real.
      if (choice.market === "MS 1.5 ÜST" && total === 0 && minute >= 45 && minute <= 65) {
        const activeMatch = Number(statsM.pressure || 0) >= 10
          && (Number(statsM.shotsOnTarget || 0) >= 2
            || Number(statsM.totalShots || 0) >= 8
            || Number(statsM.corners || 0) >= 6);
        if (!activeMatch) return null;
      }
      if (choice.market === "MS 2.5 ÜST" && total >= 3) return null;
      if (choice.market === "MS 3.5 ÜST" && total >= 4) return null;

      // Değer filtresi canlı oran varsa onu, yoksa açıkça etiketlenmiş maç önü oranını kullanır.
      // 1 gol varken MS 1.5 ÜST, 55. dakikadan sonra yeterli oran/form/baskı desteği varsa değerlendirilebilir.
      if (live && choice.market === "MS 1.5 ÜST" && total === 1) {
        if (minute < 60 || minute > 70) return null;
        if (Number(choice.odd || 0) < 1.50) return null;
        if (Number(formPct || 0) < 55) return null;
        if (Number(choice.probability || 0) < 55 || Number(choice.probability || 0) > 82) return null;
        if (Number(statsM.pressure || 0) < 10) return null;
        if (Number(statsM.shotsOnTarget || 0) < 1 && Number(statsM.totalShots || 0) < 6) return null;
      }
      // Tek gol varken 2.5 ÜST en az iki gol daha gerektirir; sadece gerçek baskı ve yeterli fiyatla aday.
      if (live && choice.market === "MS 2.5 ÜST" && total === 1) {
        if (Number(choice.odd || 0) < 1.65) return null;
        if (Number(formPct || 0) < 55) return null;
        if (Number(statsM.pressure || 0) < 18) return null;
        if (Number(statsM.shotsOnTarget || 0) < 3 && Number(statsM.totalShots || 0) < 12) return null;
        if (minute >= 72 && Number(statsM.pressure || 0) < 22) return null;
      }

      const lineNum = Number(String(choice.market).match(/(\d)[.,](\d)/)?.[0]?.replace(",", ".") || 0);
      const needed = choice.market.startsWith("MS ") ? Math.max(0, Math.ceil(lineNum + 0.01) - total) : 1;

      // Geç dakikada çok gol ihtiyacı + düşük baskı = red.
      if (minute >= 66 && needed > 1 && statsM.pressure < 16) return null;
      if (minute >= 72 && needed > 1 && statsM.pressure < 22) return null;
      if (minute >= 78 && needed >= 1 && statsM.pressure < 20) return null;
      if (minute >= 75 && choice.market === "MS 3.5 ÜST" && (needed > 1 || statsM.pressure < 26)) return null;

      // KG VAR: geride kalan favori takım baskısı şart.
      if (choice.market === "KG VAR") {
        if (total >= 2 && Number(fixture.homeScore || 0) > 0 && Number(fixture.awayScore || 0) > 0) return null; // zaten KG var
        if (leader && favorite && leader !== favorite) {
          const trailing = leader === "home" ? "away" : "home";
          const p = statsM[trailing] || {};
          const trailingPressure = Number(p.shotsOnTarget || 0) * 2.5 + Number(p.totalShots || 0) * 0.45 + Number(p.corners || 0) * 0.8;
          if (trailingPressure < 5.5 || Number(formPct || 0) < 50) return null;
          liveBonus += Math.min(14, trailingPressure * 0.55);
        } else if (!leader) {
          // Beraberlikte her iki tarafın da şut baskısı olmalı.
          const hp = Number(statsM.home?.shotsOnTarget || 0) + Number(statsM.away?.shotsOnTarget || 0);
          if (hp < 2 && statsM.pressure < 8) return null;
        }
      }

      // 0-0 / 1-0 senaryolarında erken-orta canlı: baskı eşiği.
      if (minute >= 60 && minute <= 70 && total === 0 && choice.market === "MS 0.5 ÜST") {
        const activeMatch = Number(statsM.pressure || 0) >= 8 &&
          (Number(statsM.shotsOnTarget || 0) >= 1 || Number(statsM.totalShots || 0) >= 6 || Number(statsM.corners || 0) >= 4);
        if (!activeMatch) return null;
      }
      if (firstHalfLive && choice.market === "İY 0.5 ÜST") {
        const pressureNeed = minute >= 41 ? 12 : minute >= 33 ? 10 : 8;
        const shotsNeed = minute >= 41 ? 2 : 1;
        const activeFirstHalf = Number(statsM.pressure || 0) >= pressureNeed &&
          (Number(statsM.shotsOnTarget || 0) >= shotsNeed ||
           Number(statsM.totalShots || 0) >= (minute >= 41 ? 7 : 5) ||
           Number(statsM.corners || 0) >= (minute >= 41 ? 4 : 3));
        if (!activeFirstHalf) return null;
      }
      if (firstHalfLive && choice.market === "İY 1.5 ÜST") {
        const activeFirstHalfTwoGoals = Number(statsM.pressure || 0) >= (minute >= 41 ? 14 : 10) &&
          (Number(statsM.shotsOnTarget || 0) >= 2 ||
           Number(statsM.totalShots || 0) >= (minute >= 41 ? 8 : 6) ||
           Number(statsM.corners || 0) >= 4);
        if (!activeFirstHalfTwoGoals) return null;
      }

      // Genel baskı bonusu (isabetli şut ağırlıklı).
      liveBonus += Math.min(16, statsM.pressure * 0.28);
      // Dakika ilerledikçe üst gol piyasalarına hafif ceza (zaman riski).
      if (/MS [23][.,][05] ÜST/.test(choice.market)) {
        liveBonus -= Math.max(0, (minute - 60) * 0.22);
      }
    }

    if (choice.probability < minMarketPct[choice.market]) return null;
    if (formPct != null && formPct < minFormPct[choice.market]) return null;
    const estimatedPct = formPct == null ? Number(choice.probability) : Number(choice.probability) * 0.55 + Number(formPct) * 0.45;
    const impliedPct = Number(choice.odd) > 1.01 ? 100 / Number(choice.odd) : null;
    const valueEdge = impliedPct == null ? null : estimatedPct - impliedPct;
    // Prefer probability supported by both market and form, while rewarding genuine price value;
    // never choose a long price merely because the odds are high.
    const valueBonus = valueEdge == null ? 0 : Math.max(-8, Math.min(8, valueEdge * 0.45));
    const score = choice.probability * 0.62 + (formPct == null ? 0 : formPct * 0.20) + liveBonus + valueBonus
      - (live && choice.market === "MS 3.5 ÜST" ? Math.max(0, minute - 65) * 0.4 : 0);
    return {
      ...choice,
      formPct, estimatedPct: Math.round(estimatedPct * 10) / 10, valueEdge: valueEdge == null ? null : Math.round(valueEdge * 10) / 10,
      score,
      statsSummary: live ? statsM : null,
      liveContext: live ? { minute, total, pressure: statsM.pressure, neededGoals: choice.market.startsWith("MS ") ? Math.max(0, Math.ceil(Number(String(choice.market).match(/(\d)[.,](\d)/)?.[0]?.replace(",", ".") || 0) + 0.01) - total) : null } : null
    };
  }).filter(Boolean).sort((a, b) => b.score - a.score);

  if (preferredMarket) {
    const preferred = ranked.find(x => x.market === preferredMarket);
    if (preferred) return preferred;
  }
  if (ranked[0]) return ranked[0];

  // Gevşek fallback sadece maç önü analizinde kullanılabilir; canlıda eşikleri aşamaz.
  const fallback = live ? null : choices
    .filter(choice => Number.isFinite(Number(choice.probability)) && Number(choice.probability) >= 35)
    .sort((x, y) => Number(y.probability) - Number(x.probability) || Number(x.rank || 9) - Number(y.rank || 9))[0];
  if (fallback) return { ...fallback, score: Number(fallback.probability), fallbackUsed: true };

  // No usable odds: provide an explicitly heuristic score/minute scenario, never fake odds.
  const fallbackMarket = null; // Skor senaryosu gerçek oranlı piyasa tercihi yerine kullanılamaz.
  if (fallbackMarket) {
    return { market: fallbackMarket, bookmaker: "Skor/dakika senaryosu", oddsTiming: "scenario-estimate",
      probability: null, formPct: null, score: 1, fallbackUsed: true };
  }
  return null;
}

async function sendTelegram(text) {
  if (!TELEGRAM_BOT_TOKEN || !TELEGRAM_CHAT_ID) {
    return { sent: false, reason: "TELEGRAM_BOT_TOKEN veya TELEGRAM_CHAT_ID tanımlı değil." };
  }
  const response = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify({ chat_id: TELEGRAM_CHAT_ID, text, disable_web_page_preview: true }),
    signal: AbortSignal.timeout(12000)
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok || !result.ok) throw new Error(result.description || `Telegram HTTP ${response.status}`);
  return { sent: true, messageId: result.result?.message_id ?? null };
}

function couponMessage(coupon) {
  const heading = coupon.type === "surprise" ? "🎲 WINSCOPE MAÇ ÖNÜ SÜRPRİZ 10 MAÇ" :
    coupon.type === "live" ? "⚡ WINSCOPE CANLI EN GÜVENİLİR TEK TERCİH" :
    "🎯 WINSCOPE MAÇ ÖNÜ KUPONU";
  const lines = [heading, `Tarih: ${coupon.date || "Bugün"}`, ""];
  coupon.picks.forEach((p, i) => {
    lines.push(`${i + 1}. ${p.home} - ${p.away}`);
    lines.push(`Ana tercih: ${p.market}`);
    if (coupon.type === "live") {
      lines.push(`Alternatif tercih: ${p.alternativeMarket || "Yeterli takım sinyali yok"}`);
      lines.push(`Gol baskısı: ${p.pressureSide || "Belirlenemedi"}${p.pressureTeam ? ` (${p.pressureTeam})` : ""}`);
      if (p.alternativeBasis) lines.push(`Takım yönü dayanağı: ${p.alternativeBasis}`);
    }
    lines.push(`Lig: ${p.league}`);
    if (coupon.type === "live" || p.isLive) {
      if (p.minute != null) lines.push(`Dakika: ${p.minute}' | Skor: ${p.currentScore || "—"}`);
      if (p.source) lines.push(`Kaynak: ${p.source}`);
      if (p.oddsBasis) lines.push(`Oran dayanağı: ${p.oddsBasis}`);
      if (Array.isArray(p.statsSummary) && p.statsSummary.length) {
        lines.push(`Canlı istatistik: ${p.statsSummary.join(" · ")}`);
      }
      if (p.marketProbability != null) lines.push(`Piyasa olasılığı: %${Number(p.marketProbability).toFixed(1)}`);
      if (p.formSupport != null) lines.push(`Form desteği: %${Number(p.formSupport).toFixed(0)}`);
    }
    lines.push("");
  });
  if (coupon.type === "live") {
    lines.push("Dayanak: canlı oran varsa canlı piyasa; ilgili canlı pazar yoksa maç önü oranı açıkça ayrıştırılır. Son 5 maç formu, canlı baskı ve oran değeri birlikte değerlendirilir; gerçekleşmiş pazarlar önerilmez.");
  }
  return lines.join("\n");
}


async function getOddsForFixture(fixtureId, date) {
  // Reuse date-level odds first, then query the exact fixture. Preserve errors so
  // diagnostics can distinguish an unsupported/empty market from an API failure.
  let row = null;
  const wantedId = Number(fixtureId);
  if (date) {
    try {
      const byDate = await cachedProviderRequest(`odds-date:${date}`, `/odds?date=${encodeURIComponent(date)}`, 90000);
      row = (byDate.response || []).find(x => Number(x.fixture?.id) === wantedId) || null;
    } catch (e) {
      console.warn(`[Odds] date lookup failed date=${date}: ${e.message}`);
    }
  }
  if (!row) {
    try {
      const byFixture = await cachedProviderRequest(`odds-fixture:${wantedId}`, `/odds?fixture=${encodeURIComponent(wantedId)}`, 90000);
      row = (byFixture.response || []).find(x => Number(x.fixture?.id) === wantedId) || null;
    } catch (e) {
      console.warn(`[Odds] fixture lookup failed fixture=${wantedId}: ${e.message}`);
      throw e;
    }
  }
  if (!row) console.warn(`[Odds] no prematch odds row returned for fixture=${wantedId} date=${date || "unknown"}`);
  return row;
}

async function getFixtureForLiveAnalysis(fixtureId) {
  // /fixtures?id= can briefly disagree with /fixtures?live=all. Trust the live
  // list when it contains this fixture, avoiding a false NS response for a live match.
  const payload = await cachedProviderRequest(`fixture:${fixtureId}`, `/fixtures?id=${encodeURIComponent(fixtureId)}`, 15000);
  let row = (payload.response || []).find(x => Number(x.fixture?.id ?? x.id) === Number(fixtureId)) || null;
  if (!row) return null;
  if (normalizeProviderMatch(row).status !== "LIVE") {
    try {
      const livePayload = await cachedProviderRequest("liveList", "/fixtures?live=all", 60000);
      const liveRow = (livePayload.response || []).find(x => Number(x.fixture?.id ?? x.id) === Number(fixtureId));
      if (liveRow) row = liveRow;
    } catch (e) {
      console.warn(`[Live status] live-list verification failed fixture=${fixtureId}: ${e.message}`);
    }
  }
  return row;
}


// ── Sürpriz Senaryo Takibi: bağımsız araştırma/ölçüm modülü ──
let surpriseScanInFlight = false;
let surpriseScanDiagnostics = { at: null, dates: [], fixtures: 0, oddsRows: 0, matchedOdds: 0, parsedOver25: 0, parsedBtts: 0, candidates: 0, noOdds: 0, noTargetMarket: 0, outsideRange: 0, pages: 0, errors: [] };
const SURPRISE_ODDS_MIN = 1.50;
const SURPRISE_ODDS_MAX = 1.75;

function surpriseOddsSnapshot(row) {
  // Use the shared odds parser so the surprise module understands the same
  // bookmaker/market labels as the main analysis engine.
  const parsed = oddsForFixture(row);
  const inRange = x => Number.isFinite(Number(x?.odd)) && Number(x.odd) >= SURPRISE_ODDS_MIN && Number(x.odd) <= SURPRISE_ODDS_MAX;
  const over25Rows = parsed.filter(x => x.market === "MS 2.5 ÜST");
  const bttsRows = parsed.filter(x => x.market === "KG VAR");
  const choose = rows => rows.filter(inRange).sort((a,b) => Math.abs(a.odd - 1.625) - Math.abs(b.odd - 1.625))[0] || null;
  const over25 = choose(over25Rows);
  const bttsYes = choose(bttsRows);
  const result = {
    oneXtwo: null,
    over25: over25 ? { bookmaker: over25.bookmaker, odd: Number(over25.odd) } : null,
    bttsYes: bttsYes ? { bookmaker: bttsYes.bookmaker, odd: Number(bttsYes.odd) } : null,
    parsedOver25: over25Rows.length,
    parsedBtts: bttsRows.length,
    sawTargetMarket: over25Rows.length > 0 || bttsRows.length > 0
  };
  // Keep 1X2 context for later HT/MS surprise reporting; do not use it to
  // qualify a match for the 2.5/BTTS candidate list.
  for (const book of bookmakerRows(row)) {
    for (const bet of (book.bets || [])) {
      const name = String(bet.name || "").toLowerCase();
      if (!/match winner|1x2|full.?time result|match result|regular time result/.test(name)) continue;
      const obj = { bookmaker: String(book.name || "Kaynak belirtilmedi") };
      for (const v of (bet.values || [])) {
        const label = String(v.value ?? v.name ?? "").toLowerCase().trim();
        const odd = Number(v.odd);
        if (!Number.isFinite(odd) || odd <= 1.01) continue;
        if (/^(home|1|team 1|1 \(home\))$/.test(label)) obj.home = odd;
        if (/^(draw|x|tie)$/.test(label)) obj.draw = odd;
        if (/^(away|2|team 2|2 \(away\))$/.test(label)) obj.away = odd;
      }
      if (obj.home && obj.draw && obj.away) { result.oneXtwo = obj; break; }
    }
    if (result.oneXtwo) break;
  }
  return result;
}

function isSurpriseCandidate(snapshot) {
  return Boolean(snapshot?.over25 || snapshot?.bttsYes);
}

function htftLabel(htHome, htAway, ftHome, ftAway) {
  if (![htHome, htAway, ftHome, ftAway].every(v => Number.isFinite(Number(v)))) return null;
  const sign = (h, a) => h > a ? "1" : h < a ? "2" : "X";
  return `${sign(Number(htHome), Number(htAway))}/${sign(Number(ftHome), Number(ftAway))}`;
}

async function scanSurpriseScenarios() {
  if (!databasePool || surpriseScanInFlight) return;
  surpriseScanInFlight = true;
  let diag = null;
  try {
    await archiveDatabaseReady;
    const today = turkeyDateString();
    const tomorrowDate = new Date(`${today}T12:00:00+03:00`);
    tomorrowDate.setDate(tomorrowDate.getDate() + 1);
    const tomorrow = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Istanbul" }).format(tomorrowDate);
    diag = { at: new Date().toISOString(), dates: [today, tomorrow], fixtures: 0, oddsRows: 0, matchedOdds: 0, parsedOver25: 0, parsedBtts: 0, candidates: 0, noOdds: 0, noTargetMarket: 0, outsideRange: 0, pages: 0, errors: [] };
    // /odds is paginated independently of /fixtures. Fetch every available
    // page (up to the existing 50-page safety cap) so the scan does not inspect
    // only the first small slice of a large daily bulletin.
    for (const date of [today, tomorrow]) {
      const fixturesPayload = await cachedProviderRequest(
        `surprise-fixtures:${date}`, `/fixtures?date=${date}&timezone=Europe/Istanbul`, 5 * 60 * 1000
      );
      const firstOddsPage = await cachedProviderRequest(
        `surprise-odds:${date}:page:1`, `/odds?date=${date}&page=1`, 5 * 60 * 1000
      ).catch(err => { diag.errors.push(`${date} odds page 1: ${err.message}`); return { response: [], paging: { total: 1 } }; });
      const oddsById = new Map();
      for (const row of (firstOddsPage.response || [])) if (row.fixture?.id) oddsById.set(Number(row.fixture.id), row);
      const reportedPages = Math.max(1, Number(firstOddsPage.paging?.total || 1));
      const totalPages = Math.min(50, reportedPages);
      diag.pages += totalPages;
      if (reportedPages > totalPages) diag.errors.push(`${date}: ${reportedPages} sayfanın ilk 50 sayfası tarandı.`);
      for (let page = 2; page <= totalPages; page++) {
        try {
          const payload = await cachedProviderRequest(`surprise-odds:${date}:page:${page}`, `/odds?date=${date}&page=${page}`, 5 * 60 * 1000);
          for (const row of (payload.response || [])) if (row.fixture?.id) oddsById.set(Number(row.fixture.id), row);
        } catch (err) { diag.errors.push(`${date} odds page ${page}: ${err.message}`); break; }
      }
      const fixtureRows = fixturesPayload.response || [];
      diag.fixtures += fixtureRows.length;
      diag.oddsRows += oddsById.size;
      for (const raw of fixtureRows) {
        const match = normalizeProviderMatch(raw);
        if (!match.id || match.status !== "NS") continue;
        const kickoff = match.fixtureDate ? new Date(match.fixtureDate) : null;
        const oddsRow = oddsById.get(match.id);
        if (!oddsRow) { diag.noOdds++; continue; }
        diag.matchedOdds++;
        const snapshot = surpriseOddsSnapshot(oddsRow);
        diag.parsedOver25 += snapshot.parsedOver25 || 0;
        diag.parsedBtts += snapshot.parsedBtts || 0;
        if (!snapshot.sawTargetMarket) { diag.noTargetMarket++; continue; }
        if (!isSurpriseCandidate(snapshot)) { diag.outsideRange++; continue; }
        diag.candidates++;
        const existing = await databasePool.query(
          "SELECT opening_odds, closing_odds FROM winscope_surprise_scenarios WHERE fixture_id=$1",
          [match.id]
        );
        const current = existing.rows[0];
        const now = new Date();
        const open = current?.opening_odds || snapshot;
        // Closing snapshot is the latest available pre-kickoff quote. Stop updating after kickoff.
        const close = (!kickoff || kickoff.getTime() - now.getTime() > 0) ? snapshot : (current?.closing_odds || snapshot);
        await databasePool.query(
          `INSERT INTO winscope_surprise_scenarios
           (fixture_id,match_date,kickoff_at,league,home_team,away_team,opening_odds,closing_odds,last_snapshot_at)
           VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,NOW())
           ON CONFLICT(fixture_id) DO UPDATE SET
             kickoff_at=COALESCE(EXCLUDED.kickoff_at,winscope_surprise_scenarios.kickoff_at),
             opening_odds=winscope_surprise_scenarios.opening_odds,
             closing_odds=CASE WHEN winscope_surprise_scenarios.kickoff_at > NOW() THEN EXCLUDED.closing_odds ELSE winscope_surprise_scenarios.closing_odds END,
             last_snapshot_at=NOW()`,
          [match.id,date,kickoff,match.league,match.home,match.away,JSON.stringify(open),JSON.stringify(close)]
        );
      }
    }

    surpriseScanDiagnostics = diag;
    console.log(`[SURPRISE SCAN] ${JSON.stringify(diag)}`);

    // Settle stored candidates using the official fixture result; no result is inferred.
    const pending = await databasePool.query("SELECT fixture_id, match_date FROM winscope_surprise_scenarios WHERE settled=FALSE");
    const dates = [...new Set(pending.rows.map(r => String(r.match_date).slice(0,10)))];
    for (const date of dates) {
      const payload = await cachedProviderRequest(`surprise-settle:${date}`, `/fixtures?date=${date}&timezone=Europe/Istanbul`, 2 * 60 * 1000).catch(() => ({ response: [] }));
      const byId = new Map((payload.response || []).map(x => [Number(x.fixture?.id), x]));
      for (const row of pending.rows.filter(r => String(r.match_date).slice(0,10) === date)) {
        let raw = byId.get(Number(row.fixture_id));
        if (!raw) {
          try {
            const exact = await cachedProviderRequest(
              `surprise-settle-fixture:${row.fixture_id}`,
              `/fixtures?id=${encodeURIComponent(row.fixture_id)}`,
              30_000
            );
            raw = (exact.response || []).find(x => Number(x.fixture?.id) === Number(row.fixture_id)) || null;
          } catch (lookupError) {
            console.warn(`[Surprise settle] exact fixture lookup failed fixture=${row.fixture_id}: ${lookupError.message}`);
          }
        }
        if (!raw) continue;
        const status = String(raw.fixture?.status?.short || "").toUpperCase();
        if (!["FT","AET","PEN"].includes(status)) continue;
        const ftH = raw.goals?.home, ftA = raw.goals?.away;
        const htH = raw.score?.halftime?.home, htA = raw.score?.halftime?.away;
        // Full-time goals are sufficient to settle FT markets. Half-time data can be
        // absent from some provider responses; that must not leave the whole match pending.
        if (ftH === null || ftH === undefined || ftA === null || ftA === undefined ||
            !Number.isFinite(Number(ftH)) || !Number.isFinite(Number(ftA))) continue;
        const score = `${ftH}-${ftA}`;
        const hasHalfTime = htH !== null && htH !== undefined && htA !== null && htA !== undefined &&
          Number.isFinite(Number(htH)) && Number.isFinite(Number(htA));
        const ht = hasHalfTime ? `${htH}-${htA}` : null;
        const htft = hasHalfTime ? htftLabel(htH,htA,ftH,ftA) : null;
        const over25 = Number(ftH)+Number(ftA) > 2.5;
        const btts = Number(ftH) > 0 && Number(ftA) > 0;
        await databasePool.query(
          `UPDATE winscope_surprise_scenarios SET final_score=$2,halftime_score=$3,htft_result=$4,
           over25_outcome=$5,btts_outcome=$6,settled=TRUE,settled_at=NOW()
           WHERE fixture_id=$1 AND settled=FALSE`,
          [row.fixture_id,score,ht,htft,over25,btts]
        );
      }
    }
  } catch (error) {
    if (diag) { diag.errors.push(error.message); surpriseScanDiagnostics = diag; }
    else surpriseScanDiagnostics = { ...surpriseScanDiagnostics, at: new Date().toISOString(), errors: [error.message] };
    console.error(`[Surprise scan] ${error.message}`);
  } finally {
    surpriseScanInFlight = false;
  }
}

app.get("/api/surprise-scenarios", async (req, res) => {
  if (!databasePool) return res.status(503).json({ error: "Sürpriz Senaryo Takibi için DATABASE_URL gerekli.", rows: [] });
  try {
    await archiveDatabaseReady;
    const date = String(req.query.date || turkeyDateString());
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({ error: "Tarih YYYY-MM-DD biçiminde olmalı." });
    const result = await databasePool.query(
      `SELECT * FROM winscope_surprise_scenarios WHERE match_date=$1 ORDER BY kickoff_at NULLS LAST, home_team`,
      [date]
    );
    const rows = result.rows;
    const overallSample = await databasePool.query("SELECT COUNT(*)::int AS completed FROM winscope_surprise_scenarios WHERE settled=TRUE");
    const settled = rows.filter(r => r.settled);
    const metric = key => {
      const valid = settled.filter(r => r[key] !== null);
      const wins = valid.filter(r => r[key] === true).length;
      return { wins, losses: valid.length-wins, total: valid.length, rate: valid.length ? Math.round(wins*100/valid.length) : null };
    };
    const htft = {};
    for (const r of settled) if (["1/2","2/1","X/1","X/2","1/X","2/X"].includes(r.htft_result)) htft[r.htft_result]=(htft[r.htft_result]||0)+1;
    res.json({ date, sampleTarget: 50, rows, diagnostics: surpriseScanDiagnostics, metrics: { over25: metric("over25_outcome"), btts: metric("btts_outcome"), htftSurprises: htft, completed: Number(overallSample.rows[0]?.completed || 0) } });
  } catch (error) { res.status(500).json({ error: error.message, rows: [] }); }
});


app.get("/api/surprise-thesis", async (req, res) => {
  if (!databasePool) return res.status(503).json({error:"Sürpriz tez araştırması için DATABASE_URL gerekli.",rows:[]});
  try {
    await archiveDatabaseReady;
    const date=String(req.query.date||turkeyDateString());
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({error:"Tarih YYYY-MM-DD biçiminde olmalı.",rows:[]});
    const result=await databasePool.query(
      "SELECT * FROM winscope_surprise_scenarios WHERE match_date=$1 ORDER BY kickoff_at NULLS LAST,home_team",
      [date]
    );
    const all=await databasePool.query(
      "SELECT htft_result,opening_odds,closing_odds FROM winscope_surprise_scenarios WHERE settled=TRUE"
    );
    const favorite=snapshot=>{
      const x=snapshot?.oneXtwo;
      if (!x) return null;
      const vals=[["1",Number(x.home)],["X",Number(x.draw)],["2",Number(x.away)]]
        .filter(([,v])=>Number.isFinite(v)&&v>1);
      vals.sort((a,b)=>a[1]-b[1]);
      return vals[0]?.[0]||null;
    };
    const rows=result.rows.map(r=>({
      ...r,
      opening_favorite:favorite(r.opening_odds),
      closing_favorite:favorite(r.closing_odds),
      halftime_score:r.halftime_score||null,
      final_score:r.final_score||null
    }));
    const htft={};
    for (const r of all.rows) if (r.htft_result) htft[r.htft_result]=(htft[r.htft_result]||0)+1;
    const count=key=>all.rows.filter(r=>r.htft_result===key).length;
    const diag=surpriseScanDiagnostics||{};
    res.json({
      date,rows,diagnostics:{
        at:diag.at||null,fixtures:Number(diag.fixtures||0),oddsRows:Number(diag.oddsRows||0),
        with1x2:Number(diag.matchedOdds||0),saved:Number(diag.candidates||0),errors:diag.errors||[],
        note:"Bu görünüm mevcut sürpriz senaryo taramasında saklanan maçları gösterir; tüm fikstürlerdeki tüm 1X2 oranlarının bağımsız tam örneklemi değildir."
      },
      sample:{total:all.rowCount,settled:all.rowCount,htft,homeToAwayTurnarounds:count("1/2"),awayToHomeTurnarounds:count("2/1")}
    });
  } catch(error) { res.status(500).json({error:error.message,rows:[]}); }
});

function rankSingleMatchChoices(choices, mode = "prematch") {
  const allowed = choices.filter(x => x.odd >= 1.15 && x.odd <= 2.10);
  return allowed.sort((a, b) => {
    // Conservative odds first; tie-break with market hierarchy, not invented percentages.
    return Math.abs(a.odd - 1.35) - Math.abs(b.odd - 1.35) || a.rank - b.rank;
  });
}


async function sendCouponAutomatically(coupon, chosen) {
  // Günün maç önü kuponu bildirimleri analiz dönemi boyunca kapalı.
  // Canlı tek tercih ve 10 maçlık sürpriz bildirimleri etkilenmez.
  if (coupon?.type === "prematch") {
    console.log(`[AUTO DAILY DISABLED] Günün kuponu Telegram gönderimi kapalı: date=${coupon.date || "?"}`);
    return { sent: false, disabled: true, reason: "Günün maç önü kuponu Telegram bildirimi geçici olarak kapalı." };
  }
  await archiveDatabaseReady;
  const originalPicks = coupon.picks || [];
  const alreadySent = new Set(telegramSentKeys);
  if (databasePool && originalPicks.length) {
    try {
      const ids = originalPicks.map(p => Number(p.fixtureId)).filter(Boolean);
      if (ids.length) {
        const rows = await databasePool.query(
          "SELECT fixture_id, coupon_type, market FROM winscope_telegram_delivery_sent WHERE fixture_id = ANY($1::bigint[])", [ids]
        );
        for (const row of rows.rows) alreadySent.add(telegramDeliveryKey(row.fixture_id, row.coupon_type, row.market));
      }
    } catch (error) { console.warn(`[Telegram] Tekrar kontrolü DB'de yapılamadı: ${error.message}`); }
  }
  const remainingPicks = originalPicks.filter(p => !Number(p.fixtureId) ||
    !alreadySent.has(telegramDeliveryKey(p.fixtureId, coupon.type, p.market)));
  if (!remainingPicks.length) return { sent: false, duplicateSuppressed: true, reason: "Bu maç ve tercih pazarı daha önce gönderilmiş; tekrar gönderilmedi." };
  const remainingKeys = new Set(remainingPicks.map(p => telegramDeliveryKey(p.fixtureId, coupon.type, p.market)));
  coupon = { ...coupon, picks: remainingPicks };
  chosen = (chosen || []).filter(p => !Number(p.fixtureId) || remainingKeys.has(telegramDeliveryKey(p.fixtureId, coupon.type, p.market)));
  const signature = `${coupon.date}|${coupon.type}|${chosen.map(p => `${p.fixtureId}:${p.market}`).sort().join(",")}`;
  const now = Date.now();
  for (const [key, at] of telegramDeliveryCache) if (now - at > 24 * 60 * 60 * 1000) telegramDeliveryCache.delete(key);
  if (telegramDeliveryCache.has(signature)) {
    return { sent: false, duplicateSuppressed: true, reason: "Bu kupon imzası daha önce gönderilmiş; tekrar gönderilmedi." };
  }
  try {
    const result = await sendTelegram(couponMessage(coupon));
    if (result.sent) {
      telegramDeliveryCache.set(signature, now);
      if (telegramDeliveryCache.size > 500) telegramDeliveryCache.delete(telegramDeliveryCache.keys().next().value);
      if (coupon.autoGenerated) {
        for (const p of (coupon.picks || [])) {
          if (p.fixtureId) autoSentFixtureKeys.add(autoLivePickKey(coupon.type, coupon.date, p));
        }
      }
      for (const p of (coupon.picks || [])) {
        const fixtureId = Number(p.fixtureId);
        if (!fixtureId) continue;
        const deliveryKey = telegramDeliveryKey(fixtureId, coupon.type, p.market);
        telegramSentKeys.add(deliveryKey);
        if (databasePool) {
          try {
            await databasePool.query(
              `INSERT INTO winscope_telegram_delivery_sent(fixture_id, coupon_type, market, match_date, telegram_message_id)
               VALUES ($1, $2, $3, $4::date, $5) ON CONFLICT (fixture_id, coupon_type, market) DO NOTHING`,
              [fixtureId, coupon.type, String(p.market || ""),
               /^\d{4}-\d{2}-\d{2}$/.test(String(coupon.date || "")) ? coupon.date : null,
               result.messageId]
            );
          } catch (error) { console.warn(`[Telegram] Tekrar kaydı saklanamadı fixture=${fixtureId}: ${error.message}`); }
        }
      }
      const sourceLabel = coupon.type === "live" ? "Canlı en güvenilir tek tercih" : coupon.type === "surprise" ? "Maç önü sürpriz kuponu" : "Günün kuponu";
      for (const p of (coupon.picks || [])) {
        const fixtureId = Number(p.fixtureId);
        if (!fixtureId) continue;
        const score = String(p.currentScore || "0-0");
        const goalTrack = { home:p.home, away:p.away, league:p.league, sourceLabel, baselineScore:score };
        goalTrackedFixtures.set(fixtureId, goalTrack);
        await persistGoalTracking(fixtureId, goalTrack);
        // Kupon üretilirken bilinen skor başlangıç kabul edilir.
        if (!goalScoreCache.has(fixtureId)) goalScoreCache.set(fixtureId, score);
        if (coupon.type === "live") {
          const trackedMarket = String(p.market || "");
          const existingLive = livePredictionTracking.find(x => x.fixtureId === fixtureId && x.market === trackedMarket);
          if (!existingLive) {
            const trackedLive = {
              fixtureId, home: String(p.home || ""), away: String(p.away || ""),
              market: trackedMarket, league: String(p.league || ""),
              matchDate: String(coupon.date || new Date().toISOString().slice(0,10)), startScore: score,
              minute: Number.isFinite(Number(p.minute)) ? Number(p.minute) : null,
              actualScore: null, outcome: null, settled: false, createdAt: new Date().toISOString()
            };
            livePredictionTracking.unshift(trackedLive);
            if (livePredictionTracking.length > 500) livePredictionTracking.length = 500;
            if (databasePool) {
              try {
                await databasePool.query(
                  `INSERT INTO winscope_live_predictions(fixture_id,home_team,away_team,market,signal_key,league,match_date,start_score,minute)
                   VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(fixture_id,market) DO NOTHING`,
                  [trackedLive.fixtureId,trackedLive.home,trackedLive.away,trackedLive.market,
                   `${trackedLive.fixtureId}:${trackedLive.market}`,trackedLive.league,
                   /^\\d{4}-\\d{2}-\\d{2}$/.test(trackedLive.matchDate) ? trackedLive.matchDate : null,
                   trackedLive.startScore,trackedLive.minute]
                );
              } catch (error) { console.error(`[Live tracking] fixture=${fixtureId}: ${error.message}`); }
            }
          }
        }
      }
    }
    return result;
  } catch (error) {
    console.error(`[Telegram] Otomatik kupon gönderimi başarısız (${coupon.type}):`, error.message);
    return { sent: false, error: error.message };
  }
}


function isExcludedAnalysisCompetition(match) {
  // Kullanıcının kapsamı: yalnızca kadın organizasyonları ve yaş grubu/U takımları hariç.
  // B takımları, rezerv olmayan diğer erkek senior takımlar ve milli takımlar dahildir.
  const text = `${match.league || ""} ${match.country || ""} ${match.home || ""} ${match.away || ""}`
    .toLocaleLowerCase("en")
    .replace(/[’']/g, " ")
    .replace(/[._-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const women = /\b(women|woman|ladies|feminine|femenino|feminin|womens|女子|女性)\b/i.test(text);
  const ageGroup = /\b(?:u\s*\d{1,2}|under\s*\d{1,2}|youth|junior|academy|juvenil|jeugd|sub\s*\d{1,2}|amateur youth)\b/i.test(text);
  // Kapsam yalnızca kadın organizasyonları ve yaş grubu/U takımları hariçtir.
  // Erkek senior ligleri, rezerv etiketi taşımayan ligler ve hazırlık maçları dahildir.
  return women || ageGroup;
}

function automaticLeaguePriority(match) {
  const league = String(match.league || "").toLowerCase();
  const country = String(match.country || "").toLowerCase();
  if (league.includes("premier league") || league === "la liga" || league.includes("serie a") || league.includes("bundesliga") || league.includes("ligue 1")) return 1;
  if (league.includes("eredivisie") || league.includes("primeira liga") || league.includes("championship") || league.includes("champions league") || league.includes("europa league") || league.includes("conference league")) return 2;
  if (["england", "spain", "italy", "germany", "france", "portugal", "netherlands"].includes(country)) return 3;
  return 4;
}

async function createCouponByMode(date, mode = "prematch", options = {}) {
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error("Geçerli bir maç tarihi seç.");
  const isLiveMode = mode === "live";
  const fixturePath = isLiveMode ? "/fixtures?live=all" : `/fixtures?date=${encodeURIComponent(date)}&timezone=Europe/Istanbul`;
  const fixtureKey = isLiveMode ? "liveList" : `fixtures:${date}`;
  const fixturePayload = await cachedProviderRequest(fixtureKey, fixturePath, isLiveMode ? 60_000 : 60_000);
  const allFixtures = (fixturePayload.response || []).map(normalizeProviderMatch)
    .filter(m => m.id && !isExcludedAnalysisCompetition(m) &&
      (isLiveMode ? isFreshLiveFixture(m) && Number(m.minute || 0) >= 20 && Number(m.minute || 0) <= 90 : m.status === "NS"));
  // Büyük ligleri önceliklendir; aynı öncelikte erken başlayacak maçları öne al.
  allFixtures.sort((a, b) => automaticLeaguePriority(a) - automaticLeaguePriority(b) ||
    String(a.fixtureDate || "").localeCompare(String(b.fixtureDate || "")));
  // Otomatik tarama ilk birkaç maçla sınırlı kalmasın; API istek kuyruğu hız sınırını korur.
  // Maç önü havuzunu sabit 20/35 maçla kesme: bültenin tamamını oran eşleştirmesine al.
  // Canlı taramada API kotası ve hız için ayrı, sınırlı havuz kullanılır.
  // Genişletilmiş otomatik canlı tarama: uygun maç ilk 12'de değilse kaçırılmasın.
  // API kota koruması, önbellek ve istek kuyruğu aynen korunur.
  const fixtures = isLiveMode
    ? allFixtures
    : allFixtures;
  if (!fixtures.length) return { draftId:`coupon-${Date.now()}`, date, type:mode, status:"NO_MATCHES", picks:[], message:isLiveMode ? "Şu anda uygun dakika aralığında canlı maç bulunamadı." : "Seçilen tarihte başlamamış maç bulunamadı." };

  const dateOdds = new Map();
  if (!isLiveMode) {
    // API-Football /odds uç noktası sayfalanır. Tek sayfayı okumak 390 maçın yalnızca
    // küçük bir bölümünün oranlarını getirir; toplam sayfa bitene kadar sayfaları tara.
    try {
      const first = await cachedProviderRequest(`odds-date:${date}:page:1`, `/odds?date=${encodeURIComponent(date)}&page=1`, 15 * 60 * 1000);
      for (const row of (first.response || [])) if (row.fixture?.id) dateOdds.set(Number(row.fixture.id), row);
      const reportedPages = Math.max(1, Number(first.paging?.total || 1));
      const totalPages = Math.min(50, reportedPages);
      if (reportedPages > totalPages) console.warn(`[Coupon] Güvenlik sınırı: ${reportedPages} oran sayfasının ilk ${totalPages} sayfası kullanılıyor.`);
      for (let page = 2; page <= totalPages; page++) {
        const payload = await cachedProviderRequest(`odds-date:${date}:page:${page}`, `/odds?date=${encodeURIComponent(date)}&page=${page}`, 15 * 60 * 1000);
        for (const row of (payload.response || [])) if (row.fixture?.id) dateOdds.set(Number(row.fixture.id), row);
      }
      console.log(`[Coupon] Piyasa oran sayfaları tamamlandı: date=${date}, pages=${totalPages}, oddsFixtures=${dateOdds.size}`);
    } catch (e) { console.warn(`[Coupon] date odds pagination: ${e.message}`); }
  }
  const candidates = [], errors = [];
  const rejected = { noOdds: 0, noIds: 0, noForm: 0, noStats: 0, noMarket: 0, noSignal: 0, apiErrors: 0, duplicate: 0 };
  let fixturesToAnalyze = fixtures;
  if (!isLiveMode) {
    const withBulkOdds = fixtures.filter(f => dateOdds.has(f.id));
    const withoutBulkOdds = fixtures.filter(f => !dateOdds.has(f.id));
    // Önce bütün fikstürlerin oran sayfalarını tara; takım formu API kotasını korumak için
    // en fazla 50 oranlı ve 10 oran-yedek fikstürde çekilir. Canlı istatistik çağrısı yoktur.
    fixturesToAnalyze = [...withBulkOdds.slice(0, 50), ...withoutBulkOdds.slice(0, (options.automatic ? 0 : 2))];
  }
  let analyzedFixtures = 0;
  // Maç önü kuponunda ilk 2 adayı bulunca durma: daha geniş örneklemden
  // en iyi 2 tercihi sıralayabilmek için 10 aday hedefle. Nihai kupon boyutu 2 kalır.
  const targetPicks = mode === "surprise" ? 10 : mode === "prematch" ? 10 : 1;
  for (const fixture of fixturesToAnalyze) {
    // Yeterli sayıda yeni, doğrulanmış aday oluştuğunda gereksiz API çağrılarını kes.
    const uniqueCandidateCount = options.automatic
      ? candidates.filter(p => !autoSentFixtureKeys.has(autoLivePickKey(mode, date, p))).length
      : candidates.length;
    if (!isLiveMode && uniqueCandidateCount >= targetPicks) break;
    analyzedFixtures++;
    try {
      let marketOddsRow = null, prematchOddsRow = null, oddsBasis = "";
      if (isLiveMode) {
        const [prePayload, liveOddsPayload, statsPayload, homeForm, awayForm] = await Promise.all([
          cachedProviderRequest(`odds-fixture:${fixture.id}`, `/odds?fixture=${fixture.id}`, 90000).catch(()=>({response:[]})),
          cachedProviderRequest(`odds-live-fixture:${fixture.id}`, `/odds/live?fixture=${fixture.id}`, 8000).catch(()=>({response:[]})),
          cachedProviderRequest(`stats:${fixture.id}`, `/fixtures/statistics?fixture=${fixture.id}`, 10000),
          fetchTeamRecentForm(fixture.homeId, fixture.id, fixture.leagueId, fixture.season, "home"),
          fetchTeamRecentForm(fixture.awayId, fixture.id, fixture.leagueId, fixture.season, "away")
        ]);
        prematchOddsRow = (prePayload.response || []).find(row=>Number(row.fixture?.id)===fixture.id) || null;
        // Live odds providers may return a fixture in the bulk live feed even when
        // the fixture-specific query is empty. Check both shapes, without substituting
        // pre-match odds for a live price in the live selection logic.
        let liveOddsRow = (liveOddsPayload.response || []).find(row=>Number(row.fixture?.fixture?.id ?? row.fixture?.id ?? row.fixtureId ?? row.id)===fixture.id) || null;
        if (!liveOddsRow) {
          try {
            const allLiveOddsPayload = await cachedProviderRequest("odds-live-all", "/odds/live", 10000);
            liveOddsRow = (allLiveOddsPayload.response || []).find(row=>Number(row.fixture?.fixture?.id ?? row.fixture?.id ?? row.fixtureId ?? row.id)===fixture.id) || null;
            console.log(`[LIVE ODDS BULK CHECK] ${JSON.stringify({match:`${fixture.home} - ${fixture.away}`,fixtureId:fixture.id,fixtureQueryResults:(liveOddsPayload.response||[]).length,bulkResults:(allLiveOddsPayload.response||[]).length,bulkMatchFound:Boolean(liveOddsRow)})}`);
          } catch (e) {
            console.warn(`[LIVE ODDS BULK ERROR] fixture=${fixture.id}: ${e.message}`);
          }
        }
        marketOddsRow = liveOddsRow; // Canlı tercih için maç önü oranı kesinlikle yedek olamaz.
        const statsRows = statsPayload.response || [];
        const stats = liveStatsMetrics(statsRows, fixture);
        if (!marketOddsRow) {
          rejected.noOdds++;
          console.warn(`[LIVE ODDS MISSING] ${JSON.stringify({match:`${fixture.home} - ${fixture.away}`,fixtureId:fixture.id,liveOddsResults:(liveOddsPayload.response||[]).length,prematchOddsFound:Boolean(prematchOddsRow),statsRows:statsRows.length,statsAvailable:stats.available})}`);
          continue;
        }
        if (!homeForm.available || !awayForm.available) { rejected.noForm++; continue; }
        // Canlı istatistikler yardımcı sinyaldir; eksik olduklarında takım formu + gerçek canlı oranla
        // daha yüksek eşik kullanılır. İstatistik değerleri hiçbir zaman tahmin edilmez.
        const chosen = chooseSupportedMarket(liveOddsRow, mode, fixture, {home:homeForm,away:awayForm}, stats, prematchOddsRow);
        if (!chosen) { rejected.noSignal++; continue; }
        oddsBasis = `Gerçek canlı oran · ${chosen.bookmaker}`;
        const alternative = teamGoalAlternative(fixture, {home:homeForm, away:awayForm}, stats, liveOddsRow, prematchOddsRow);
        candidates.push({
          fixtureId: fixture.id, league: fixture.league, country: fixture.country,
          home: fixture.home, away: fixture.away, fixtureDate: fixture.fixtureDate,
          market: chosen.market, alternativeMarket: alternative?.market || null,
          pressureSide: alternative?.pressureSide || 'Belirlenemedi', pressureTeam: alternative?.pressureTeam || null,
          alternativeBasis: alternative?.basis || 'Takım bazlı canlı istatistik veya son 5 maç verisi eksik; alternatif taraf uydurulmadı.',
          source: chosen.bookmaker, oddsTiming: chosen.oddsTiming,
          internalOdd: chosen.odd, marketProbability: chosen.probability,
          formSupport: chosen.formPct, score: chosen.score,
          minute: fixture.minute, currentScore: `${fixture.homeScore}-${fixture.awayScore}`,
          isLive: true, oddsBasis,
          statsSummary: [
            `İsabetli şut: ${stats.shotsOnTarget}`,
            `Toplam şut: ${stats.totalShots}`,
            `Korner: ${stats.corners}`,
            `Baskı skoru: ${Number(stats.pressure || 0).toFixed(1)}`
          ]
        });
      } else {
        marketOddsRow = dateOdds.get(fixture.id) || null;
        if (!marketOddsRow) {
          const payload = await cachedProviderRequest(`odds-fixture:${fixture.id}`, `/odds?fixture=${fixture.id}`, 90000);
          marketOddsRow = (payload.response || []).find(row=>Number(row.fixture?.id)===fixture.id) || null;
        }
        if (!marketOddsRow) { rejected.noOdds++; continue; }
        if (!fixture.homeId || !fixture.awayId) { rejected.noIds++; continue; }
        const [homeForm, awayForm] = await Promise.all([fetchTeamRecentForm(fixture.homeId,fixture.id,fixture.leagueId,fixture.season,"home"),fetchTeamRecentForm(fixture.awayId,fixture.id,fixture.leagueId,fixture.season,"away")]);
        if (!homeForm.available || !awayForm.available) { rejected.noForm++; continue; }
        const chosen = chooseSupportedMarket(marketOddsRow, mode, fixture, {home:homeForm,away:awayForm}, null, marketOddsRow);
        if (!chosen) { rejected.noSignal++; continue; }
        oddsBasis = "API-Football maç önü son mevcut oran kaydı; resmî kapanış olduğu garanti edilemez";
        candidates.push({fixtureId:fixture.id,league:fixture.league,country:fixture.country,home:fixture.home,away:fixture.away,
          fixtureDate:fixture.fixtureDate,market:chosen.market,source:chosen.bookmaker,internalOdd:chosen.odd,marketProbability:chosen.probability,
          formSupport:chosen.formPct,score:chosen.score,minute:null,currentScore:"0-0",isLive:false,oddsBasis,statsSummary:null});
      }
    } catch(e) {
      rejected.apiErrors++;
      const message = /istek sınırına ulaşıldı/i.test(e.message) ? "API-Football istek sınırı; kuyruk beklemesi devrede" : e.message;
      errors.push(`${fixture.home} - ${fixture.away}: ${message}`);
      if (/istek sınırına ulaşıldı/i.test(e.message)) break;
    }
  }
  // Otomatik gönderimlerde aynı gün daha önce gönderilmiş maçları yeniden seçme.
  const availableCandidates = options.automatic
    ? candidates.filter(p => !autoSentFixtureKeys.has(autoLivePickKey(mode, date, p)))
    : candidates;
  rejected.duplicate = candidates.length - availableCandidates.length;
  console.log(`[COUPON SCAN ${mode.toUpperCase()}] date=${date} live=${isLiveMode} fixtures=${allFixtures.length} prioritized=${fixtures.length} analyzed=${analyzedFixtures} candidates=${candidates.length} available=${availableCandidates.length} rejected=${JSON.stringify(rejected)} seasonStats=home-away-blend youthReserveWomen=excluded oddsPagesMax=50 errors=${errors.length}`);
  availableCandidates.sort((a,b)=>b.score-a.score || b.formSupport-a.formSupport || a.internalOdd-b.internalOdd);
  const count = mode === "surprise" ? 10 : mode === "prematch" ? 2 : 1;
  const chosen = availableCandidates.slice(0,count);
  if (!chosen.length || (mode === "prematch" && chosen.length < 2)) {
    const needed = mode === "prematch" ? 2 : 1;
    return {draftId:`coupon-${Date.now()}`,date,type:mode,status:"NO_MATCHES",picks:[],
      message:`Maç önü oranı + son 5 maç formu${isLiveMode ? " + canlı istatistik" : ""} eşiklerini geçen yeterli maç yok (gereken: ${needed}). Kupon zorlanmadı.`,
      detail:`Fikstür: ${allFixtures.length}; oran sayfasından eşleşen: ${dateOdds.size}; form/statistik için incelenen: ${fixturesToAnalyze.length}; aday: ${candidates.length}; elenme: oran=${rejected.noOdds}, form=${rejected.noForm}, canlı-istatistik=${rejected.noStats}, piyasa-sinyali=${rejected.noSignal}, API-hatası=${rejected.apiErrors}, tekrar=${rejected.duplicate}. ${errors.slice(0,2).join(" | ")}`};
  }
  // internalOdd / score iç skorlama; canlı kupon Telegram'da olasılık + form + dk/skor gösterilsin.
  const publicPicks = chosen.map(({ internalOdd, score, ...p }) => p);
  const draftId = `coupon-${Date.now()}`;
  const coupon = {draftId,date,type:mode,isLive:isLiveMode,status:"READY",picks:publicPicks,autoGenerated:Boolean(options.automatic),
    message:mode==="live" ? "Tek canlı tercih: yalnızca maç önü oranı kullanıldı; dakika/skor + son 5 maç formu + canlı şut/korner baskısı değerlendirildi." :
      mode==="surprise" ? `Sürpriz kupon: ${publicPicks.length} maç (en fazla 10); yalnızca oran ve son 5 maç formu eşiğini geçen adaylar eklendi.` :
      "Maç önü kuponu: en az iki maç, maç önü son mevcut oran ve son 5 gerçek skor formu birlikte değerlendirildi."};
  const archiveCoupon = {date,type:mode,picks:publicPicks,createdAt:new Date().toISOString()};
  archives.coupons.unshift(archiveCoupon);
  archives.coupons=archives.coupons.slice(0,50);
  await saveArchiveItem("coupon", archiveCoupon);
  try {
    await archiveDatabaseReady;
    const trackingResult = await saveCouponTracking(coupon);
    console.log(`[Coupon tracking] Yeni kupon kayıtları: ${trackingResult.saved}; PostgreSQL=${trackingResult.persistent}`);
  } catch (trackingError) {
    console.error(`[Coupon tracking] Yeni kupon kaydedilemedi: ${trackingError.message}`);
  }
  // Onay butonu olmadan, kupon başarıyla üretildiğinde Telegram'a otomatik gönder.
  coupon.telegram = await sendCouponAutomatically(coupon, chosen);
  return coupon;
}

app.get("/api/telegram/status", async (_req, res) => {
  if (!TELEGRAM_BOT_TOKEN || !TELEGRAM_CHAT_ID) {
    return res.status(503).json({
      ok: false,
      configured: false,
      botActive: false,
      chatConfigured: Boolean(TELEGRAM_CHAT_ID),
      message: "Render Environment içinde TELEGRAM_BOT_TOKEN ve TELEGRAM_CHAT_ID kontrol edilmeli."
    });
  }
  try {
    const response = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getMe`, {
      signal: AbortSignal.timeout(10000)
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || !result.ok) {
      return res.status(502).json({
        ok: false, configured: true, botActive: false,
        message: result.description || `Telegram API HTTP ${response.status}`
      });
    }
    return res.json({
      ok: true, configured: true, botActive: true,
      botUsername: result.result?.username || null,
      chatConfigured: true,
      message: "Bot token geçerli ve Telegram botu aktif. Chat ID'ye mesaj gönderme yetkisi ayrıca test edilmelidir."
    });
  } catch (e) {
    return res.status(502).json({
      ok: false, configured: true, botActive: false,
      message: `Telegram bağlantı testi başarısız: ${e.message}`
    });
  }
});

app.get("/api/health", (_req, res) => res.json({
  ok: true, apiKeyConfigured: Boolean(API_KEY),
  telegramConfigured: Boolean(TELEGRAM_BOT_TOKEN && TELEGRAM_CHAT_ID),
  databaseConfigured: Boolean(databasePool),
  provider: "API-Football", oddsPolicy: "pre-match odds for pre-match analysis; live analysis uses live odds only; no pre-match fallback for live picks", livePolicy: "period-aware; settled markets excluded; fresh fixture/odds recheck before Telegram", teamFormPolicy: "last five completed matches plus cached league-season home/away goal averages", oddsValuesHidden: true
}));

// Compatibility route used by the current index.html live-goal button.
// It performs a real live-data check and never invents odds or statistics.
async function analyzeLiveFixture(fixture, liveOddsRow, statsRows, teamForms = null, prematchOddsRow = null) {
  const stats = liveStatsMetrics(statsRows || [], fixture);
  const liveParsedMarkets = oddsForFixture(liveOddsRow || null, { includeFirstHalfBtts: true });
  const prematchParsedMarkets = oddsForFixture(prematchOddsRow || null);
  const prematchBttsRows = prematchParsedMarkets.filter(x =>
    x.market === "KG VAR" && Number.isFinite(Number(x.odd)) &&
    Number(x.odd) >= 1.50 && Number(x.odd) <= 1.73
  );
  const prematchBttsEligible = prematchBttsRows.length > 0;
  const markets = liveParsedMarkets.filter(x =>
    ["İY 0.5 ÜST", "İY 1.5 ÜST", "MS 0.5 ÜST", "MS 1.5 ÜST", "MS 2.5 ÜST", "MS 3.5 ÜST", "MS 4.5 ÜST", "MS 5.5 ÜST", "EV 0.5 ÜST", "DEP 0.5 ÜST", "EV 1.5 ÜST", "DEP 1.5 ÜST", "KG VAR"].includes(x.market) &&
    (x.market !== "KG VAR" || prematchBttsEligible)
  );
  const minute = Number(fixture.minute || 0);
  const homeGoals = Number(fixture.homeScore || 0), awayGoals = Number(fixture.awayScore || 0);
  const total = homeGoals + awayGoals;
  const phase = String(fixture.periodStatus || "").toUpperCase();
  const isFirstHalf = phase === "1H" || (!phase && minute < 45);
  const isHalftime = phase === "HT";
  const isSecondHalf = ["2H", "ET", "LIVE", "IN_PLAY"].includes(phase) || (!phase && minute >= 45);
  const formsAvailable = Boolean(teamForms?.home?.available && teamForms?.away?.available);
  // Live-only profile signal: include full-time scoring/conceding rates as well as HT rates.
  // This prevents productive teams being discarded just because provider live stats are sparse.
  const strongGoalProfile = formsAvailable && (
    (Number(teamForms.home.teamScoredPct || 0) >= 70 && Number(teamForms.home.avgGoalsFor || 0) >= 1.0) ||
    (Number(teamForms.away.teamScoredPct || 0) >= 70 && Number(teamForms.away.avgGoalsFor || 0) >= 1.0) ||
    (Number(teamForms.home.over25Pct || 0) >= 60 && Number(teamForms.away.over25Pct || 0) >= 60) ||
    (Number(teamForms.home.bttsPct || 0) >= 60 && Number(teamForms.away.bttsPct || 0) >= 60) ||
    Number(teamForms.home.htOver15Pct || 0) >= 50 ||
    Number(teamForms.away.htOver15Pct || 0) >= 50 ||
    Number(teamForms.home.recent?.htOver15Pct || 0) >= 60 ||
    Number(teamForms.away.recent?.htOver15Pct || 0) >= 60 ||
    Number(teamForms.home.htTeamScoredPct || 0) >= 70 ||
    Number(teamForms.away.htTeamScoredPct || 0) >= 70
  );
  const remaining = Math.max(1, 95 - minute);
  const sideLambda = (side, ownForm, opponentForm) => {
    const sidePressure = Number(side?.shotsOnTarget || 0) * 2.6 + Number(side?.totalShots || 0) * 0.42 + Number(side?.corners || 0) * 0.7;
    const pressureMultiplier = stats.available
      ? Math.max(strongGoalProfile ? 0.85 : 0.50, Math.min(1.55, 0.62 + sidePressure / 11))
      : (strongGoalProfile ? 0.95 : 0.75);
    const liveLambda = 1.25 * remaining / 90 * pressureMultiplier;
    const formRate = formsAvailable
      ? Math.max(0.08, 0.58 * Number(ownForm?.avgGoalsFor || 0) + 0.42 * Number(opponentForm?.avgGoalsAgainst || 0))
      : null;
    const recentFormRate = formsAvailable && ownForm?.recent?.avgGoalsFor != null && opponentForm?.recent?.avgGoalsAgainst != null
      ? Math.max(0.08, 0.58 * Number(ownForm.recent.avgGoalsFor) + 0.42 * Number(opponentForm.recent.avgGoalsAgainst))
      : null;
    const blendedRate = formRate == null ? null :
      (recentFormRate == null ? formRate : 0.70 * formRate + 0.30 * recentFormRate);
    const formLambda = blendedRate == null ? null : blendedRate * remaining / 90 * pressureMultiplier;
    let combined = formLambda == null ? liveLambda : 0.55 * liveLambda + 0.45 * formLambda;
    // Finishing/first-half scoring profile can lift the estimate even when shot volume is modest.
    if (ownForm?.available && ownForm.htTeamScoredPct != null) {
      const htFinishFactor = 0.90 + Math.min(0.22, Math.max(0, ownForm.htTeamScoredPct - 50) / 250);
      combined *= htFinishFactor;
    }
    return Math.max(0.001, combined);
  };
  const lambdaHome = sideLambda(stats.home, teamForms?.home, teamForms?.away);
  const lambdaAway = sideLambda(stats.away, teamForms?.away, teamForms?.home);
  const homeNextGoalProbability = homeGoals > 0 ? 1 : poissonProbabilityAtLeast(1, lambdaHome, 0);
  const awayNextGoalProbability = awayGoals > 0 ? 1 : poissonProbabilityAtLeast(1, lambdaAway, 0);
  const homeScoresAgainProbability = poissonProbabilityAtLeast(1, lambdaHome, 0);
  const awayScoresAgainProbability = poissonProbabilityAtLeast(1, lambdaAway, 0);
  const anyNextGoalProbability = 1 - Math.exp(-(lambdaHome + lambdaAway));
  const activeStats = stats.available && (
    Number(stats.shotsOnTarget || 0) >= 2 || Number(stats.totalShots || 0) >= 8 || Number(stats.corners || 0) >= 6
  );
  const liveSignalAvailable = activeStats || strongGoalProfile;
  const goalDirection = homeScoresAgainProbability >= awayScoresAgainProbability * 1.20 && homeScoresAgainProbability - awayScoresAgainProbability >= 0.08
    ? "home"
    : awayScoresAgainProbability >= homeScoresAgainProbability * 1.20 && awayScoresAgainProbability - homeScoresAgainProbability >= 0.08
      ? "away" : "balanced";
  const candidates = [];
  const evaluations = [];
  const rejected = { noLiveOdds: !liveOddsRow, noStats: !stats.available, noTeamForm: !formsAvailable, noMarket: markets.length === 0,
    lowOdds: 0, noValue: 0, settled: 0, wrongPeriod: 0, weakGoalSignal: 0, wrongGoalDirection: 0 };

  // Gol beklentisi önce doğrulanır. Zayıf canlı istatistikle yalnızca oran yüksek diye sinyal üretme.
  // Late-match probability naturally falls with remaining time. Do not require
  // a fixed 62% chance of ANY goal before even evaluating priced markets.
  // Real live odds + usable live stats + market-specific EV/edge remain mandatory.
  if ((!stats.available && !strongGoalProfile) || !liveSignalAvailable || minute < 10 || minute > 90 || isHalftime) {
    rejected.weakGoalSignal = 1;
  } else {
    for (const item of markets) {
      const odd = Number(item.odd);
      if (!Number.isFinite(odd) || odd < 1.50) { rejected.lowOdds++; continue; }
      if (liveMarketAlreadySettled(item.market, fixture)) { rejected.settled++; continue; }
      const ms = item.market.match(/^MS ([0-9]+(?:[.,][0-9]+)?) ÜST$/);
      const ht = item.market.match(/^İY ([0-9]+(?:[.,][0-9]+)?) ÜST$/);
      const isHomeMarket = item.market.startsWith("EV ");
      const isAwayMarket = item.market.startsWith("DEP ");
      if ((isFirstHalf && (!ht || isHomeMarket || isAwayMarket)) ||
          (isSecondHalf && ht) || isHalftime) {
        rejected.wrongPeriod++; continue;
      }
      if (!isFirstHalf && !isSecondHalf) { rejected.wrongPeriod++; continue; }

      let modelProbability = 0;
      let lambdaUsed = null;
      let scenarioSide = null;
      if (isHomeMarket || isAwayMarket) {
        const isHome = isHomeMarket;
        const scored = isHome ? homeGoals : awayGoals;
        const lambda = isHome ? lambdaHome : lambdaAway;
        const line = item.market.includes("1.5") ? 2 : 1;
        const needed = Math.max(0, line - scored);
        if (needed === 0) { rejected.settled++; continue; }
        modelProbability = poissonProbabilityAtLeast(line, lambda, scored);
        lambdaUsed = lambda;
        scenarioSide = isHome ? "home" : "away";
        const sideGoalProbability = isHome ? homeScoresAgainProbability : awayScoresAgainProbability;
        const otherGoalProbability = isHome ? awayScoresAgainProbability : homeScoresAgainProbability;
        if (sideGoalProbability < 0.25 || (goalDirection !== "balanced" && scenarioSide !== goalDirection && sideGoalProbability < otherGoalProbability * 0.90)) {
          rejected.wrongGoalDirection++; continue;
        }
      } else if (item.market === "KG VAR") {
        if (homeGoals > 0 && awayGoals > 0) { rejected.settled++; continue; }

        // KG Var için henüz gol atmamış takımın kendi gol sinyalini doğrula.
        // Önde olan takımın baskısı, gerideki takımın gol ihtimali yerine geçemez.
        const unscoredSide = homeGoals === 0 ? "home" : (awayGoals === 0 ? "away" : null);
        const sideStats = unscoredSide ? stats[unscoredSide] : null;
        const sideForm = unscoredSide ? teamForms?.[unscoredSide] : null;
        const sideShotsOnTarget = Number(sideStats?.shotsOnTarget || 0);
        const sideTotalShots = Number(sideStats?.totalShots || 0);
        const sideCorners = Number(sideStats?.corners || 0);
        // Gerideki/henüz gol atmamış takım için daha seçici sinyal:
        // tek başına genel maç baskısı KG Var üretmeye yetmez.
        const sidePressure =
          sideShotsOnTarget >= 2 ||
          (sideShotsOnTarget >= 1 && sideTotalShots >= 5) ||
          (sideTotalShots >= 6 && sideCorners >= 2);
        const sideFormSupport = Boolean(
          sideForm?.available &&
          Number(sideForm.sampleSize || 0) >= 5 &&
          Number(sideForm.recentSampleSize || 0) >= 3 &&
          Number(sideForm.teamScoredPct || 0) >= 65 &&
          Number(sideForm.recent?.teamScoredPct || 0) >= 55
        );
        if (unscoredSide && !sidePressure && !sideFormSupport) {
          rejected.weakGoalSignal++;
          continue;
        }

        // 1-0 / 2-0 gibi skorlarda yalnızca gol atmamış tarafın olasılığı;
        // 0-0'da iki takımın gol olasılıklarının çarpımı kullanılır.
        modelProbability = unscoredSide === "home" ? homeScoresAgainProbability
          : unscoredSide === "away" ? awayScoresAgainProbability
          : homeScoresAgainProbability * awayScoresAgainProbability;
        lambdaUsed = unscoredSide === "home" ? lambdaHome
          : unscoredSide === "away" ? lambdaAway
          : lambdaHome + lambdaAway;
      } else {
        const line = Number((ms || ht)[1].replace(',', '.'));
        const current = ms ? total : (fixture.htHomeScore != null && fixture.htAwayScore != null
          ? Number(fixture.htHomeScore) + Number(fixture.htAwayScore) : total);
        const timeLeft = ms ? remaining : Math.max(1, 45 - minute);
        const lambda = ms ? lambdaHome + lambdaAway : (lambdaHome + lambdaAway) * timeLeft / remaining;
        modelProbability = poissonProbabilityAtLeast(line, lambda, current);
        lambdaUsed = lambda;
        // Bir takımın gol atma olasılığı zayıfsa toplam gol pazarı da sırf fiyat avantajıyla seçilemez.
        // Remaining-time probability is evaluated by modelProbability and EV below;
        // a second fixed 62% gate here would suppress almost every 66–90' candidate.
      }

      const marketProbability = Number(item.probability) / 100;
      if (!Number.isFinite(marketProbability) || marketProbability <= 0 || marketProbability >= 1) { rejected.noMarket = true; continue; }
      const edge = modelProbability - marketProbability;
      const ev = modelProbability * odd - 1;
      evaluations.push({ market: item.market, odd, bookmaker: item.bookmaker, modelProbability, marketProbability, edge, ev,
        lambda: lambdaUsed, scenarioSide });

      // Değer eşiği: istatistik + son 5 maç varsa daha düşük, yoksa daha yüksek edge/EV aranır.
      // A lower raw probability can still be a valid late-game value at a fair
      // live price. Edge and EV, not an arbitrary 60% probability floor, decide.
      const minEdge = formsAvailable ? 0.025 : 0.035;
      const minEv = formsAvailable ? 0.035 : 0.045;
      const minProbability = item.market === "KG VAR"
        ? (homeGoals + awayGoals > 0 ? 0.42 : 0.25)
        : (isHomeMarket || isAwayMarket ? 0.30 : 0.25);
      if (modelProbability < minProbability || edge < minEdge || ev < minEv) { rejected.noValue++; continue; }

      // Skor senaryosuna uymayan pazar seçilmesin. Örn. deplasman golü daha olasıysa evin ikinci golü ana tercih olamaz.
      let directionBonus = 0;
      if (goalDirection !== "balanced") {
        if (scenarioSide && scenarioSide !== goalDirection) { rejected.wrongGoalDirection++; continue; }
        if (!scenarioSide && item.market !== "KG VAR") directionBonus = -0.035;
      }
      // Market uygunluğu: skor 1-0 / 2-0 gibi tek taraflıysa genel gol pazarı,
      // KG Var'dan daha kapsayıcıdır. KG Var yalnızca gol atmamış tarafın güçlü
      // baskısı mevcutsa bu önceliği aşabilir.
      let marketFitBonus = 0;
      if (homeGoals + awayGoals > 0 && item.market === "KG VAR") {
        const unscoredSide = homeGoals === 0 ? "home" : (awayGoals === 0 ? "away" : null);
        const unscoredStats = unscoredSide ? stats[unscoredSide] : null;
        const unscoredPressure = Number(unscoredStats?.shotsOnTarget || 0) >= 2 ||
          (Number(unscoredStats?.shotsOnTarget || 0) >= 1 && Number(unscoredStats?.totalShots || 0) >= 5) ||
          (Number(unscoredStats?.totalShots || 0) >= 6 && Number(unscoredStats?.corners || 0) >= 2);
        marketFitBonus = unscoredPressure ? 0 : -18;
      } else if (homeGoals + awayGoals > 0 && ms) {
        marketFitBonus = 8;
      }
      const score = edge * 100 + ev * 100 + modelProbability * 20 + directionBonus * 100 + marketFitBonus;
      const confidence = (
        stats.available && activeStats && formsAvailable &&
        edge >= 0.10 && ev >= 0.10 && modelProbability >= 0.70
      ) ? "HIGH" : (
        stats.available && activeStats &&
        edge >= 0.06 && ev >= 0.06 && modelProbability >= minProbability + 0.05
      ) ? "MEDIUM" : "LOW";
      candidates.push({ market: item.market, bookmaker: item.bookmaker, modelProbability, marketProbability, edge, ev,
        odd, confidence, statsAvailable: stats.available, teamFormAvailable: formsAvailable, strongGoalProfile,
        minEdgeRequired: minEdge, minEVRequired: minEv, scenarioSide, selectionScore: score });
    }
  }
  candidates.sort((a,b) => b.selectionScore - a.selectionScore || (b.ev + b.edge) - (a.ev + a.edge));
  evaluations.sort((a,b) => (b.ev + b.edge) - (a.ev + a.edge) || b.ev - a.ev);
  const chosen = candidates[0] || null;
  const directionLabel = goalDirection === "home" ? "Ev sahibi golü daha olası" : goalDirection === "away" ? "Deplasman golü daha olası" : "Gol yönü net değil";
  const pctValue = value => Number.isFinite(Number(value)) ? Math.round(Number(value)) : null;
  const averagePct = (a, b) => {
    const values = [a, b].map(pctValue).filter(v => v != null);
    return values.length ? Math.round(values.reduce((sum, v) => sum + v, 0) / values.length) : null;
  };
  const oneXTwoRows = oddsForFixture(prematchOddsRow || null).filter(x =>
    x.market === "MS 1" && x.outcomeProbabilities &&
    [x.outcomeProbabilities.home, x.outcomeProbabilities.draw, x.outcomeProbabilities.away].every(v => Number.isFinite(Number(v)))
  ).sort((a, b) => (/bet365/i.test(b.bookmaker) - /bet365/i.test(a.bookmaker)));
  const oneXTwo = oneXTwoRows[0]?.outcomeProbabilities || null;
  const livePercentages = {
    home: {
      htGoal: pctValue(teamForms?.home?.htTeamScoredPct),
      htSampleSize: Number(teamForms?.home?.htSampleSize || 0),
      ftGoal: pctValue(teamForms?.home?.teamScoredPct),
      sampleSize: Number(teamForms?.home?.sampleSize || 0)
    },
    away: {
      htGoal: pctValue(teamForms?.away?.htTeamScoredPct),
      htSampleSize: Number(teamForms?.away?.htSampleSize || 0),
      ftGoal: pctValue(teamForms?.away?.teamScoredPct),
      sampleSize: Number(teamForms?.away?.sampleSize || 0)
    },
    match: {
      btts: averagePct(teamForms?.home?.bttsPct, teamForms?.away?.bttsPct),
      over25: averagePct(teamForms?.home?.over25Pct, teamForms?.away?.over25Pct),
      ms1: oneXTwo ? Number(oneXTwo.home.toFixed(1)) : null,
      draw: oneXTwo ? Number(oneXTwo.draw.toFixed(1)) : null,
      ms2: oneXTwo ? Number(oneXTwo.away.toFixed(1)) : null,
      resultLean: oneXTwo
        ? (oneXTwo.home >= oneXTwo.draw && oneXTwo.home >= oneXTwo.away ? "MS 1 eğilimi" :
           oneXTwo.away >= oneXTwo.draw && oneXTwo.away >= oneXTwo.home ? "MS 2 eğilimi" : "Beraberlik eğilimi")
        : null
    },
    note: "Takım yüzdeleri son tamamlanmış maçlardan; KG VAR ve 2.5 ÜST iki takım form ortalamasından; MS 1/X/2 maç önü 1X2 oranlarından hesaplanır."
  };
  return {
    fixtureId: fixture.id, currentScore: `${homeGoals}-${awayGoals}`, minute, periodStatus: phase,
    mainPick: chosen?.market || null, alternative: candidates[1]?.market || null,
    source: chosen?.bookmaker || null, valueScore: chosen?.ev ?? null, edge: chosen?.edge ?? null,
    oddsTiming: liveOddsRow ? "live" : "unavailable",
    stats: { available: stats.available, totalShots: stats.totalShots, shotsOnTarget: stats.shotsOnTarget, corners: stats.corners,
      pressure: Number((stats.pressure || 0).toFixed(1)), home: stats.home, away: stats.away },
    livePercentages,
    teamForm: { available: formsAvailable,
      homeSample: teamForms?.home?.sampleSize || 0, awaySample: teamForms?.away?.sampleSize || 0,
      homeRecentSample: teamForms?.home?.recentSampleSize || 0, awayRecentSample: teamForms?.away?.recentSampleSize || 0,
      homeHT15: teamForms?.home?.htOver15Pct ?? null, awayHT15: teamForms?.away?.htOver15Pct ?? null,
      homeHTBTTS: teamForms?.home?.htBttsPct ?? null, awayHTBTTS: teamForms?.away?.htBttsPct ?? null },
    goalScenario: { direction: goalDirection, label: directionLabel,
      homeNextGoalProbability: Number((homeScoresAgainProbability * 100).toFixed(1)),
      awayNextGoalProbability: Number((awayScoresAgainProbability * 100).toFixed(1)),
      anyNextGoalProbability: Number((anyNextGoalProbability * 100).toFixed(1)),
      activeStats, strongGoalProfile,
      signalSource: activeStats ? (strongGoalProfile ? "live-stats+goal-profile" : "live-stats") : (strongGoalProfile ? "last-10-and-last-5-goal-profile" : "none") },
    prematchBtts: prematchBttsEligible ? prematchBttsRows.map(x => ({ bookmaker:x.bookmaker, odd:Number(x.odd) })) : [],
    marketEvaluations: evaluations,
    goalSignal: { level: chosen ? "Değer adayı" : "Tercih yok", score: chosen ? Math.round(chosen.edge * 100) : 0,
      note: chosen ? `${directionLabel}; canlı oran, canlı istatistik ve son 10 maç + son 5 maç gol profili birlikte değerlendirildi.`
        : (!liveOddsRow ? "Gerçek canlı oran bulunamadı." : isHalftime ? "Devre arası; canlı tercih bekletildi." :
          "Gol olasılığı, son 10/5 maç gol profili, canlı istatistik ve değer eşiklerini birlikte karşılayan tercih bulunmadı.") },
    oddsBasis: liveOddsRow ? "Yalnızca gerçek canlı oranlar kullanıldı; maç önü oranı yedek yapılmadı." : "Canlı oran bulunamadı; maç önü oranı kullanılmadı.",
    reasonCounts: rejected,
    note: chosen ? `En güçlü canlı aday: ${chosen.market}; gol senaryosu: ${directionLabel}. Kesin sonuç değildir.`
      : "Maç tarandı ancak gol beklentisi veya uygun pazar yeterince doğrulanmadı; tercih üretilmedi."
  };
}

app.get("/api/match/:id/live-goal-analysis", async (req, res) => {
  try {
    const fixtureId = Number(req.params.id);
    if (!Number.isInteger(fixtureId) || fixtureId <= 0) return res.status(400).json({ error: "Geçersiz maç kimliği." });
    const row = await getFixtureForLiveAnalysis(fixtureId);
    if (!row) return res.status(404).json({ error: "Maç verisi bulunamadı." });
    const fixture = normalizeProviderMatch(row);
    if (fixture.status !== "LIVE") return res.status(409).json({ error: "Bu maç API tarafından canlı olarak işaretlenmiyor." });
    const fixtureDate = fixture.fixtureDate ? String(fixture.fixtureDate).slice(0, 10) : null;
    const [statsPayload, oddsPayload, prematchOddsRow] = await Promise.all([
      cachedProviderRequest(`stats:${fixtureId}`, `/fixtures/statistics?fixture=${fixtureId}`, 15000).catch(e => { console.warn(`[Live analysis] stats failed fixture=${fixtureId}: ${e.message}`); return { response: [] }; }),
      cachedProviderRequest(`odds-live-fixture:${fixtureId}`, `/odds/live?fixture=${fixtureId}`, 10000).catch(e => { console.warn(`[Live analysis] live odds failed fixture=${fixtureId}: ${e.message}`); return { response: [] }; }),
      getOddsForFixture(fixtureId, fixtureDate).catch(e => { console.warn(`[Live analysis] prematch 1X2 percentages unavailable fixture=${fixtureId}: ${e.message}`); return null; })
    ]);
    let liveOddsRow = (oddsPayload.response || []).find(x => Number(x.fixture?.fixture?.id ?? x.fixture?.id ?? x.fixtureId ?? x.id) === fixtureId) || null;
    if (!liveOddsRow) {
      try { const all = await cachedProviderRequest("odds-live-all", "/odds/live", 10000); liveOddsRow = (all.response || []).find(x => Number(x.fixture?.fixture?.id ?? x.fixture?.id ?? x.fixtureId ?? x.id) === fixtureId) || null; } catch {}
    }
    const [homeGoalProfile, awayGoalProfile] = await Promise.all([
      fetchLiveGoalProfile(fixture.homeId, fixture.id),
      fetchLiveGoalProfile(fixture.awayId, fixture.id)
    ]);
    const liveGoalForms = { home: homeGoalProfile, away: awayGoalProfile };
    return res.json(await analyzeLiveFixture(fixture, liveOddsRow, statsPayload.response || [], liveGoalForms, prematchOddsRow));
  } catch (error) {
    const message = String(error?.message || error);
    const limited = /429|rate.?limit|quota|istek sınırı/i.test(message);
    res.status(limited ? 429 : 502).json({ error: limited ? "API kotası/sınırı nedeniyle canlı analiz şu an alınamıyor." : "Canlı analiz alınamadı.", detail: message });
  }
});

app.get("/api/match/:id/analyze", async (req, res) => {
  try {
    const payload = await cachedProviderRequest(`fixture:${req.params.id}`, `/fixtures?id=${encodeURIComponent(req.params.id)}`, 15000);
    const row = payload.response?.[0];
    if (!row) return res.status(404).json({ error: "Maç verisi bulunamadı." });

    const match = normalizeProviderMatch(row);
    // WinScope test modu: canlı maç kartta görünür, analiz ise tamamen maç önü verisiyle yapılır.
    // Canlı oranlar ve canlı istatistikler bu endpointte kesinlikle kullanılmaz.
    const prematchFixture = {
      ...match,
      status: "NS",
      minute: null,
      homeScore: 0,
      awayScore: 0,
      htHomeScore: null,
      htAwayScore: null
    };

    const [prematchRow, homeForm, awayForm] = await Promise.all([
      getOddsForFixture(match.id, match.fixtureDate ? String(match.fixtureDate).slice(0, 10) : null).catch(e => {
        console.warn(`[Prematch analysis] odds failed fixture=${match.id}: ${e.message}`); return null;
      }),
      fetchTeamRecentForm(match.homeId, match.id, match.leagueId, match.season, "home"),
      fetchTeamRecentForm(match.awayId, match.id, match.leagueId, match.season, "away")
    ]);
    const forms = { home: homeForm, away: awayForm };
    let scores = scorePrediction(prematchFixture, homeForm, awayForm, null, prematchRow);

    // Tercih yalnızca maç önü piyasasında gerçekten bulunan oranlardan seçilir.
    const chosen = prematchRow
      ? chooseSupportedMarket(prematchRow, "prematch", prematchFixture, forms, null, prematchRow)
      : null;
    if (chosen?.market) scores = scorePrediction(prematchFixture, homeForm, awayForm, null, prematchRow, chosen.market);
    const ftMatch = String(scores.fullTimeScore || "").match(/(\d+)\s*[-:]\s*(\d+)/);
    const scoreSuggestsBtts = Boolean(ftMatch && Number(ftMatch[1]) > 0 && Number(ftMatch[2]) > 0);
    const alternative = chosen
      ? chooseSupportedMarket(prematchRow, "prematch", prematchFixture, forms, null, prematchRow, chosen.market, scoreSuggestsBtts ? "KG VAR" : null)
      : null;

    const percentages = analysisPercentages(prematchRow, homeForm, awayForm);
    const marketNames = oddsForFixture(prematchRow).map(x => x.market);
    const marketAvailable = name => marketNames.includes(name);
    res.json({
      fixtureId: match.id,
      matchStatus: match.status,
      analysisMode: "PREMATCH_ONLY",
      halfTimeScore: scores.halfTimeScore,
      fullTimeScore: scores.fullTimeScore,
      alternativeFullTimeScore: scores.alternativeFullTimeScore || "Alternatif skor hesaplanamadı",
      // Tanılama: ana Günün Analizleri motorunun sürümünü ve koşulsuz skorunu açıkça bildir.
      scoreModelVersion: scores.modelVersion || "UNKNOWN",
      scoreModelMethod: scores.scoreModelMethod || "UNKNOWN",
      scoreProbability: scores.scoreProbability ?? null,
      expectedGoals: scores.expectedGoals || null,
      topScoreCandidates: scores.topScoreCandidates || [],
      marketScenarioScore: scores.marketScenarioScore || null,
      marketScenarioCandidates: scores.marketScenarioCandidates || [],
      scoreCondition: scores.scoreCondition || "UNCONDITIONAL",
      scoreProbabilityType: scores.scoreProbabilityType || "UNCONDITIONAL",
      scoreBasis: scores.scoreBasis || "Maç önü oranları ve erişilebilen son 5 maç formu",
      mainPick: chosen?.market || "Maç önü oranlarından doğrulanmış tercih bulunamadı",
      alternative: alternative?.market || "Doğrulanmış alternatif bulunamadı",
      livePick: "Canlı analiz kapalı — maç önü analizi",
      livePickBasis: "Canlı oran ve canlı istatistik kullanılmıyor.",
      marketPercentages: percentages,
      // Sayısal maç önü piyasa fiyatları arşiv/onay kaydı için API cevabında tutulur;
      // istemci bunları ekrana basmaz.
      rawPrematchMarkets: oddsForFixture(prematchRow).map(x => ({
        market:x.market, bookmaker:x.bookmaker, probability:Number(x.probability),
        overOdd:x.overOdd ?? null, underOdd:x.underOdd ?? null,
        yesOdd:x.yesOdd ?? null, noOdd:x.noOdd ?? null,
        homeOdd:x.homeOdd ?? null, drawOdd:x.drawOdd ?? null, awayOdd:x.awayOdd ?? null
      })),
      markets: {
        ht1x2: marketAvailable("İY 1X2"),
        ft1x2: marketAvailable("MS 1X2"),
        ht05: marketAvailable("İY 0.5 ÜST"),
        ht15: marketAvailable("İY 1.5 ÜST"),
        btts: marketAvailable("KG VAR"),
        ms15: marketAvailable("MS 1.5 ÜST"),
        ms25: marketAvailable("MS 2.5 ÜST"),
        ms35: marketAvailable("MS 3.5 ÜST"),
        ms55: marketAvailable("MS 5.5 ÜST"),
        ah05: marketAvailable("AH -0.5")
      },
      note: prematchRow
        ? `${chosen?.bookmaker || "Maç önü oran kaydı"} ve erişilebilen takım formu değerlendirildi. Ham oranlar arayüzde gösterilmez.`
        : "Bu maç için API-Football üzerinden maç önü oran kaydı alınamadı. Skor tahmini yalnızca mevcut takım formu verisiyle üretilebilir; oran dayanaklı tercih üretilmedi.",
      oddsBasis: prematchRow
        ? "Yalnızca API-Football maç önü oranları; canlı oranlar kullanılmadı."
        : "Maç önü oranı bulunamadı.",
      htMarketAlreadyHit: false
    });
  } catch (e) {
    res.status(502).json({ error: "Maç önü analizi üretilemedi.", detail: e.message });
  }
});

function isFreshLiveFixture(match, nowMs = Date.now()) {
  if (match.status !== "LIVE") return false;
  const kickoff = Date.parse(match.fixtureDate || "");
  // API-Football bazen önceki güne ait kapanmış/eskimiş canlı satırı döndürebiliyor.
  // Gerçekten devam eden maçlar normal koşullarda başlangıçtan itibaren 6 saati aşmaz.
  if (Number.isFinite(kickoff) && nowMs - kickoff > 6 * 60 * 60 * 1000) return false;
  return true;
}

app.get("/api/live", async (_req, res) => {
  try {
    const payload = await cachedProviderRequest("liveList", "/fixtures?live=all", 20_000);
    const raw = (payload.response || []).map(normalizeProviderMatch);
    const matches = raw.filter(m => isFreshLiveFixture(m));
    const staleLiveExcluded = raw.length - matches.length;
    if (staleLiveExcluded) console.warn(`[LIVE FIXTURE CLEANUP] staleLiveExcluded=${staleLiveExcluded} raw=${raw.length}`);
    res.json({ source: "API-Football", results: matches.length, matches, staleLiveExcluded, fetchedAt: new Date().toISOString() });
  } catch (e) { res.status(502).json({ error: "Canlı maçlar alınamadı", detail: e.message, matches: [] }); }
});

